"""Pure Nostr (NIP-01) helpers for the Buzz channel connector.

No I/O, no wall-clock: callers supply ``created_at``. BIP-340 signing is done via
``coincurve``, which ships in the optional ``buzz`` dependency extra and is imported
lazily so the rest of the app never requires it.
"""

from __future__ import annotations

import hashlib
import json
from dataclasses import dataclass
from typing import Any

_BECH32_CHARSET = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"

COINCURVE_INSTALL_HINT = "The Buzz channel requires the 'buzz' extra: run `uv sync --extra buzz` (installs coincurve for BIP-340 signing)."


def _require_coincurve():
    try:
        import coincurve
    except ImportError as exc:  # pragma: no cover - exercised via BuzzChannel.start
        raise RuntimeError(COINCURVE_INSTALL_HINT) from exc
    return coincurve


@dataclass(frozen=True)
class NostrKeys:
    secret: bytes
    pubkey_hex: str


def _bech32_polymod(values: list[int]) -> int:
    gen = [0x3B6A57B2, 0x26508E6D, 0x1EA119FA, 0x3D4233DD, 0x2A1462B3]
    chk = 1
    for v in values:
        b = chk >> 25
        chk = (chk & 0x1FFFFFF) << 5 ^ v
        for i in range(5):
            chk ^= gen[i] if ((b >> i) & 1) else 0
    return chk


def _bech32_decode(expected_hrp: str, value: str) -> bytes:
    if "1" not in value:
        raise ValueError(f"not bech32: {value!r}")
    hrp, data_part = value.rsplit("1", 1)
    if hrp != expected_hrp:
        raise ValueError(f"expected {expected_hrp!r} bech32, got {hrp!r}")
    try:
        data = [_BECH32_CHARSET.index(c) for c in data_part]
    except ValueError as exc:
        raise ValueError(f"invalid bech32 character in {value!r}") from exc
    hrp_expanded = [ord(c) >> 5 for c in hrp] + [0] + [ord(c) & 31 for c in hrp]
    if _bech32_polymod(hrp_expanded + data) != 1:
        raise ValueError(f"bad bech32 checksum in {value!r}")
    acc = bits = 0
    out = bytearray()
    for v in data[:-6]:
        acc = (acc << 5) | v
        bits += 5
        if bits >= 8:
            bits -= 8
            out.append((acc >> bits) & 0xFF)
    if len(out) != 32:
        raise ValueError(f"expected 32-byte payload in {value!r}")
    return bytes(out)


def _parse_32_bytes(value: str, bech_hrp: str) -> bytes:
    value = value.strip()
    if value.lower().startswith(f"{bech_hrp}1"):
        return _bech32_decode(bech_hrp, value.lower())
    try:
        raw = bytes.fromhex(value)
    except ValueError as exc:
        raise ValueError(f"expected 64-hex or {bech_hrp}1... value") from exc
    if len(raw) != 32:
        raise ValueError("expected exactly 32 bytes")
    return raw


def parse_private_key(value: str) -> NostrKeys:
    secret = _parse_32_bytes(value, "nsec")
    coincurve = _require_coincurve()
    pubkey = coincurve.PrivateKey(secret).public_key.format(compressed=True)[1:]
    return NostrKeys(secret=secret, pubkey_hex=pubkey.hex())


def parse_pubkey(value: str) -> str:
    return _parse_32_bytes(value, "npub").hex()


def event_id(pubkey_hex: str, created_at: int, kind: int, tags: list[list[str]], content: str) -> str:
    payload = json.dumps([0, pubkey_hex, created_at, kind, tags, content], separators=(",", ":"), ensure_ascii=False)
    return hashlib.sha256(payload.encode()).hexdigest()


def sign_event(keys: NostrKeys, kind: int, tags: list[list[str]], content: str, created_at: int) -> dict:
    coincurve = _require_coincurve()
    eid = event_id(keys.pubkey_hex, created_at, kind, tags, content)
    sig = coincurve.PrivateKey(keys.secret).sign_schnorr(bytes.fromhex(eid))
    return {"id": eid, "pubkey": keys.pubkey_hex, "created_at": created_at, "kind": kind, "tags": tags, "content": content, "sig": sig.hex()}


KIND_CHAT = 9
KIND_EDIT = 40003
KIND_AUTH = 22242
KIND_CHANNEL_META = 39000
# Relay-signed membership notifications (buzz-core's KIND_MEMBER_ADDED_NOTIFICATION /
# KIND_MEMBER_REMOVED_NOTIFICATION). Each carries ``p`` = the affected member's pubkey
# and ``h`` = the channel uuid, which is how a connected client learns it was added to
# (or removed from) a channel without reconnecting.
KIND_MEMBER_ADDED = 44100
KIND_MEMBER_REMOVED = 44101


def build_auth_event(keys: NostrKeys, relay_url: str, challenge: str, created_at: int) -> dict:
    return sign_event(keys, KIND_AUTH, [["relay", relay_url], ["challenge", challenge]], "", created_at)


def build_chat_event(keys: NostrKeys, channel_id: str, content: str, created_at: int, reply_to: str | None = None, mentions: tuple[str, ...] = ()) -> dict:
    tags: list[list[str]] = [["h", channel_id]]
    if reply_to:
        tags.append(["e", reply_to])
    tags.extend(["p", m] for m in mentions)
    return sign_event(keys, KIND_CHAT, tags, content, created_at)


def build_edit_event(keys: NostrKeys, channel_id: str, target_event_id: str, content: str, created_at: int) -> dict:
    return sign_event(keys, KIND_EDIT, [["h", channel_id], ["e", target_event_id]], content, created_at)


def verify_event(event: Any) -> bool:
    """True only when *event* carries a self-consistent id and a valid BIP-340 signature.

    Two independent checks, both required:

    1. The NIP-01 event id is RECOMPUTED from the event's own
       ``pubkey``/``created_at``/``kind``/``tags``/``content`` and must equal the
       ``id`` the sender claims -- so ``id`` cannot be borrowed from a different
       (legitimately signed) event while the payload is swapped.
    2. The Schnorr signature must verify against that id under the claimed
       ``pubkey``, which is what actually binds the payload to its author.

    Relay input is untrusted, so this NEVER raises: any missing, mistyped,
    non-hex, or wrong-length field -- or a payload that is not even a mapping --
    is simply an event that fails to verify, and callers must be able to treat
    "malformed" and "forged" identically without a try/except at every call site.
    A missing ``coincurve`` (the optional ``buzz`` extra) also lands here and
    fails closed; it is unreachable in practice because ``BuzzChannel.start()``
    already parses its private key through ``coincurve`` and would have failed
    with :data:`COINCURVE_INSTALL_HINT` long before any event arrived.
    """
    try:
        if not isinstance(event, dict):
            return False
        pubkey = event.get("pubkey")
        sig = event.get("sig")
        claimed_id = event.get("id")
        content = event.get("content")
        created_at = event.get("created_at")
        kind = event.get("kind")
        tags = event.get("tags")
        # bool is an int subclass; a JSON `true` in either numeric field would
        # otherwise serialize as "true" and silently change the canonical form.
        if not isinstance(pubkey, str) or not isinstance(sig, str) or not isinstance(claimed_id, str) or not isinstance(content, str) or not isinstance(tags, list):
            return False
        if not isinstance(created_at, int) or isinstance(created_at, bool) or not isinstance(kind, int) or isinstance(kind, bool):
            return False
        if event_id(pubkey, created_at, kind, tags, content) != claimed_id:
            return False
        coincurve = _require_coincurve()
        return bool(coincurve.PublicKeyXOnly(bytes.fromhex(pubkey)).verify(bytes.fromhex(sig), bytes.fromhex(claimed_id)))
    except Exception:
        return False


def req_frame(sub_id: str, *filters: dict) -> str:
    return json.dumps(["REQ", sub_id, *filters], separators=(",", ":"))


def event_frame(event: dict) -> str:
    return json.dumps(["EVENT", event], separators=(",", ":"))


def close_frame(sub_id: str) -> str:
    """NIP-01 ``CLOSE``: stop an individual subscription without dropping the socket.

    Needed because chat subscriptions are per channel (the relay only fans kind-9
    events out to ``#h``-scoped subscriptions), so being removed from a channel has
    to unsubscribe exactly that one -- the other channels' subscriptions, the
    discovery subscription, and the membership subscription all ride the same
    connection and must survive.
    """
    return json.dumps(["CLOSE", sub_id], separators=(",", ":"))


def tag_values(event: dict, name: str) -> list[str]:
    return [t[1] for t in event.get("tags", []) if len(t) >= 2 and t[0] == name]

"""Local persistence for runtime IM channel configuration."""

from __future__ import annotations

import json
import logging
import tempfile
import threading
from pathlib import Path
from typing import Any

logger = logging.getLogger(__name__)

RUNTIME_CHANNEL_DISABLED_FLAG = "_runtime_disabled"


class ChannelRuntimeConfigStore:
    """JSON-backed store for channel credentials entered from the UI.

    This intentionally mirrors ``ChannelStore``: local/private deployments get
    durable runtime configuration without needing a public callback URL or a
    config.yaml edit.
    """

    def __init__(self, path: str | Path | None = None) -> None:
        if path is None:
            from deerflow.config.paths import get_paths

            path = Path(get_paths().base_dir) / "channels" / "runtime-config.json"
        self._path = Path(path)
        self._path.parent.mkdir(parents=True, exist_ok=True)
        self._data: dict[str, dict[str, Any]] = self._load()
        self._lock = threading.Lock()

    def _load(self) -> dict[str, dict[str, Any]]:
        if self._path.exists():
            try:
                raw = json.loads(self._path.read_text(encoding="utf-8"))
            except (json.JSONDecodeError, OSError):
                logger.warning("Corrupt channel runtime config store at %s, starting fresh", self._path)
                return {}
            if isinstance(raw, dict):
                return {str(name): dict(value) for name, value in raw.items() if isinstance(value, dict)}
        return {}

    def _save(self) -> None:
        fd = tempfile.NamedTemporaryFile(
            mode="w",
            dir=self._path.parent,
            suffix=".tmp",
            delete=False,
        )
        try:
            try:
                Path(fd.name).chmod(0o600)
            except OSError:
                logger.debug("Unable to chmod temporary channel runtime config store at %s", fd.name, exc_info=True)
            json.dump(self._data, fd, indent=2, ensure_ascii=False)
            fd.close()
            Path(fd.name).replace(self._path)
            try:
                self._path.chmod(0o600)
            except OSError:
                logger.debug("Unable to chmod channel runtime config store at %s", self._path, exc_info=True)
        except BaseException:
            fd.close()
            Path(fd.name).unlink(missing_ok=True)
            raise

    def load_all(self) -> dict[str, dict[str, Any]]:
        with self._lock:
            return {name: dict(config) for name, config in self._data.items()}

    def get_provider_config(self, provider: str) -> dict[str, Any] | None:
        with self._lock:
            config = self._data.get(provider)
            return dict(config) if isinstance(config, dict) else None

    def set_provider_config(self, provider: str, config: dict[str, Any]) -> None:
        with self._lock:
            self._data[provider] = dict(config)
            self._save()

    def set_provider_disconnected(self, provider: str) -> None:
        with self._lock:
            self._data[provider] = {
                "enabled": False,
                RUNTIME_CHANNEL_DISABLED_FLAG: True,
            }
            self._save()

    def remove_provider_config(self, provider: str) -> bool:
        with self._lock:
            if provider not in self._data:
                return False
            del self._data[provider]
            self._save()
            return True


def _provider_enabled(channel_connections_config: Any, provider: str) -> bool:
    provider_config = getattr(channel_connections_config, provider, None)
    return bool(getattr(provider_config, "enabled", False))


def _runtime_channel_disconnected(runtime_config: dict[str, Any]) -> bool:
    return runtime_config.get(RUNTIME_CHANNEL_DISABLED_FLAG) is True and runtime_config.get("enabled") is False


def merge_runtime_channel_configs(
    channels_config: dict[str, Any],
    channel_connections_config: Any,
    *,
    store: ChannelRuntimeConfigStore | None = None,
) -> None:
    """Merge persisted runtime provider config into ``channels_config`` in-place."""
    if channel_connections_config is None or not getattr(channel_connections_config, "enabled", False):
        return

    runtime_store = store or ChannelRuntimeConfigStore()
    for provider, runtime_config in runtime_store.load_all().items():
        if not _provider_enabled(channel_connections_config, provider):
            continue
        if _runtime_channel_disconnected(runtime_config):
            channels_config.pop(provider, None)
            continue
        existing = channels_config.get(provider)
        merged = dict(existing) if isinstance(existing, dict) else {}
        merged.update(runtime_config)
        channels_config[provider] = merged


def apply_runtime_connection_config(
    channel_connections_config: Any,
    *,
    store: ChannelRuntimeConfigStore | None = None,
) -> Any:
    """Apply persisted connection metadata that lives outside ``channels``.

    Telegram uses a bot username for deep links; UI-entered values are stored
    with the runtime channel config so local restarts keep the provider
    configured.
    """
    if channel_connections_config is None or not getattr(channel_connections_config, "enabled", False):
        return channel_connections_config

    runtime_store = store or ChannelRuntimeConfigStore()
    telegram_runtime_config = runtime_store.get_provider_config("telegram")
    bot_username = ""
    if isinstance(telegram_runtime_config, dict):
        bot_username = str(telegram_runtime_config.get("bot_username") or "").strip()
    if not bot_username or not _provider_enabled(channel_connections_config, "telegram"):
        return channel_connections_config

    config = channel_connections_config.model_copy(deep=True)
    config.telegram.bot_username = bot_username
    return config

from __future__ import annotations

import asyncio
import base64
import hashlib
import inspect
import logging
from collections.abc import Awaitable, Callable
from typing import Any, cast

from app.channels.base import Channel
from app.channels.commands import is_known_channel_command
from app.channels.connection_identity import attach_connection_identity
from app.channels.message_bus import (
    InboundMessage,
    InboundMessageType,
    MessageBus,
    OutboundMessage,
    ResolvedAttachment,
)

logger = logging.getLogger(__name__)


def _file_md5(path: str) -> str:
    md5_hasher = hashlib.md5()
    with open(path, "rb") as file_obj:
        for chunk in iter(lambda: file_obj.read(1024 * 1024), b""):
            md5_hasher.update(chunk)
    return md5_hasher.hexdigest()


def _open_binary(path: str):
    return open(path, "rb")


class WeComChannel(Channel):
    def __init__(self, bus: MessageBus, config: dict[str, Any]) -> None:
        super().__init__(name="wecom", bus=bus, config=config)
        self._bot_id: str | None = None
        self._bot_secret: str | None = None
        self._ws_client = None
        self._ws_task: asyncio.Task | None = None
        self._ws_shutdown_task: asyncio.Future[Any] | None = None
        self._lifecycle_lock = asyncio.Lock()
        self._ws_frames: dict[str, dict[str, Any]] = {}
        self._ws_stream_ids: dict[str, str] = {}
        self._working_message = "Working on it..."

    @property
    def supports_streaming(self) -> bool:
        return True

    def _clear_ws_context(self, thread_ts: str | None) -> None:
        if not thread_ts:
            return
        self._ws_frames.pop(thread_ts, None)
        self._ws_stream_ids.pop(thread_ts, None)

    async def _send_ws_upload_command(self, req_id: str, body: dict[str, Any], cmd: str) -> dict[str, Any]:
        if not self._ws_client:
            raise RuntimeError("WeCom WebSocket client is not available")

        ws_manager = getattr(self._ws_client, "_ws_manager", None)
        send_reply = getattr(ws_manager, "send_reply", None)
        if not callable(send_reply):
            raise RuntimeError("Installed wecom-aibot-python-sdk does not expose the WebSocket media upload API expected by DeerFlow. Use wecom-aibot-python-sdk==0.1.6 or update the adapter.")

        send_reply_async = cast(Callable[[str, dict[str, Any], str], Awaitable[dict[str, Any]]], send_reply)
        return await send_reply_async(req_id, body, cmd)

    async def start(self) -> None:
        async with self._lifecycle_lock:
            if self._running:
                return

            bot_id = self.config.get("bot_id")
            bot_secret = self.config.get("bot_secret")
            working_message = self.config.get("working_message")

            self._bot_id = bot_id if isinstance(bot_id, str) and bot_id else None
            self._bot_secret = bot_secret if isinstance(bot_secret, str) and bot_secret else None
            self._working_message = working_message if isinstance(working_message, str) and working_message else "Working on it..."

            if not self._bot_id or not self._bot_secret:
                logger.error("WeCom channel requires bot_id and bot_secret")
                return

            try:
                from aibot import WSClient, WSClientOptions
            except ImportError:
                logger.error("wecom-aibot-python-sdk is not installed. Install it with: uv add wecom-aibot-python-sdk")
                return
            else:
                self._ws_client = WSClient(WSClientOptions(bot_id=self._bot_id, secret=self._bot_secret, logger=logger))
                self._ws_client.on("message.text", self._on_ws_text)
                self._ws_client.on("message.mixed", self._on_ws_mixed)
                self._ws_client.on("message.image", self._on_ws_image)
                self._ws_client.on("message.file", self._on_ws_file)
                self._ws_client.on("error", self._on_ws_error)
                self._ws_client.on("disconnected", self._on_ws_disconnected)
                self._ws_task = asyncio.create_task(self._ws_client.connect())
                self._ws_task.add_done_callback(self._on_ws_task_done)

                self._running = True
                self.bus.subscribe_outbound(self._on_outbound)
            logger.info("WeCom channel started")

    def _on_ws_task_done(self, task: asyncio.Task) -> None:
        if task.cancelled():
            return
        exc = task.exception()
        if exc is None:
            return
        logger.error(
            "WeCom WebSocket connection task failed: %s. Check that the network/proxy allows wss://openws.work.weixin.qq.com and that bot_id/bot_secret are valid.",
            exc,
        )

    def _on_ws_error(self, error: Any) -> None:
        logger.error("WeCom WebSocket error: %s", error)

    def _on_ws_disconnected(self, *args: Any) -> None:
        detail = f" ({args[0]})" if args else ""
        logger.warning("WeCom WebSocket disconnected%s; SDK will attempt to reconnect", detail)

    def _begin_ws_shutdown(self, ws_client: Any) -> asyncio.Future[Any] | None:
        ws_manager = getattr(ws_client, "_ws_manager", None)
        async_disconnect = getattr(ws_manager, "_async_disconnect", None)
        stop_heartbeat = getattr(ws_manager, "_stop_heartbeat", None)
        clear_pending_messages = getattr(ws_manager, "_clear_pending_messages", None)

        if inspect.iscoroutinefunction(async_disconnect) and callable(stop_heartbeat) and callable(clear_pending_messages):
            # wecom-aibot-python-sdk 1.0.2 makes disconnect() synchronous and
            # discards the task created for _async_disconnect(). Perform its
            # synchronous bookkeeping here so DeerFlow can own and await the
            # actual SDK shutdown operation without scheduling a duplicate.
            try:
                if hasattr(ws_client, "_started"):
                    ws_client._started = False
                ws_manager._is_manual_close = True
                stop_heartbeat()
                clear_pending_messages("Connection manually closed")
            except Exception:
                logger.exception("Failed to prepare WeCom WebSocket shutdown")
            return asyncio.create_task(async_disconnect())

        try:
            result = ws_client.disconnect()
        except Exception:
            logger.exception("Failed to request WeCom WebSocket disconnect")
            return None
        if inspect.isawaitable(result):
            return asyncio.ensure_future(result)
        return None

    async def stop(self) -> None:
        async with self._lifecycle_lock:
            self._running = False
            self.bus.unsubscribe_outbound(self._on_outbound)
            ws_client = self._ws_client
            ws_task = self._ws_task
            if ws_task and not ws_task.done():
                ws_task.cancel()

            shutdown_task = None
            try:
                shutdown_task = self._begin_ws_shutdown(ws_client) if ws_client else None
                self._ws_shutdown_task = shutdown_task
                tasks = [task for task in (ws_task, shutdown_task) if task is not None]
                drain_future = asyncio.gather(*tasks, return_exceptions=True) if tasks else None
                if drain_future is not None:
                    try:
                        await asyncio.shield(drain_future)
                    except asyncio.CancelledError:
                        # Caller cancellation still propagates, but only after
                        # the channel-owned tasks have completed their cleanup.
                        await drain_future
                        raise
            finally:
                if self._ws_task is ws_task:
                    self._ws_task = None
                if self._ws_client is ws_client:
                    self._ws_client = None
                if self._ws_shutdown_task is shutdown_task:
                    self._ws_shutdown_task = None
                self._ws_frames.clear()
                self._ws_stream_ids.clear()
            logger.info("WeCom channel stopped")

    async def send(self, msg: OutboundMessage, *, _max_retries: int = 3) -> None:
        if self._ws_client:
            await self._send_ws(msg, _max_retries=_max_retries)
            return
        logger.warning("[WeCom] send called but WebSocket client is not available")

    async def _on_outbound(self, msg: OutboundMessage) -> None:
        if msg.channel_name != self.name:
            return

        try:
            await self.send(msg)
        except Exception:
            logger.exception("Failed to send outbound message on channel %s", self.name)
            if msg.is_final:
                self._clear_ws_context(msg.thread_ts)
            return

        for attachment in msg.attachments:
            try:
                success = await self.send_file(msg, attachment)
                if not success:
                    logger.warning("[%s] file upload skipped for %s", self.name, attachment.filename)
            except Exception:
                logger.exception("[%s] failed to upload file %s", self.name, attachment.filename)

        if msg.is_final:
            self._clear_ws_context(msg.thread_ts)

    async def send_file(self, msg: OutboundMessage, attachment: ResolvedAttachment) -> bool:
        if not msg.is_final:
            return True
        if not self._ws_client:
            return False
        if not msg.thread_ts:
            return False
        frame = self._ws_frames.get(msg.thread_ts)
        if not frame:
            return False

        media_type = "image" if attachment.is_image else "file"
        size_limit = 2 * 1024 * 1024 if attachment.is_image else 20 * 1024 * 1024
        if attachment.size > size_limit:
            logger.warning(
                "[WeCom] %s too large (%d bytes), skipping: %s",
                media_type,
                attachment.size,
                attachment.filename,
            )
            return False

        try:
            media_id = await self._upload_media_ws(
                media_type=media_type,
                filename=attachment.filename,
                path=str(attachment.actual_path),
                size=attachment.size,
            )
            if not media_id:
                return False

            body = {media_type: {"media_id": media_id}, "msgtype": media_type}
            await self._ws_client.reply(frame, body)
            logger.debug("[WeCom] %s sent via ws: %s", media_type, attachment.filename)
            return True
        except Exception:
            logger.exception("[WeCom] failed to upload/send file via ws: %s", attachment.filename)
            return False

    async def _on_ws_text(self, frame: dict[str, Any]) -> None:
        body = frame.get("body", {}) or {}
        text = ((body.get("text") or {}).get("content") or "").strip()
        quote = (((body.get("quote") or {}).get("text") or {}).get("content") or "").strip()
        if not text and not quote:
            return
        await self._publish_ws_inbound(frame, text + (f"\nQuote message: {quote}" if quote else ""))

    async def _on_ws_mixed(self, frame: dict[str, Any]) -> None:
        body = frame.get("body", {}) or {}
        mixed = body.get("mixed") or {}
        items = mixed.get("msg_item") or []
        parts: list[str] = []
        files: list[dict[str, Any]] = []
        for item in items:
            item_type = (item or {}).get("msgtype")
            if item_type == "text":
                content = (((item or {}).get("text") or {}).get("content") or "").strip()
                if content:
                    parts.append(content)
            elif item_type in ("image", "file"):
                payload = (item or {}).get(item_type) or {}
                url = payload.get("url")
                aeskey = payload.get("aeskey")
                if isinstance(url, str) and url:
                    files.append(
                        {
                            "type": item_type,
                            "url": url,
                            "aeskey": (aeskey if isinstance(aeskey, str) and aeskey else None),
                        }
                    )
        text = "\n\n".join(parts).strip()
        if not text and not files:
            return
        if not text:
            text = "（receive image/file）"
        await self._publish_ws_inbound(frame, text, files=files)

    async def _on_ws_image(self, frame: dict[str, Any]) -> None:
        body = frame.get("body", {}) or {}
        image = body.get("image") or {}
        url = image.get("url")
        aeskey = image.get("aeskey")
        if not isinstance(url, str) or not url:
            return
        await self._publish_ws_inbound(
            frame,
            "（receive image ）",
            files=[
                {
                    "type": "image",
                    "url": url,
                    "aeskey": aeskey if isinstance(aeskey, str) and aeskey else None,
                }
            ],
        )

    async def _on_ws_file(self, frame: dict[str, Any]) -> None:
        body = frame.get("body", {}) or {}
        file_obj = body.get("file") or {}
        url = file_obj.get("url")
        aeskey = file_obj.get("aeskey")
        if not isinstance(url, str) or not url:
            return
        await self._publish_ws_inbound(
            frame,
            "（receive file）",
            files=[
                {
                    "type": "file",
                    "url": url,
                    "aeskey": aeskey if isinstance(aeskey, str) and aeskey else None,
                }
            ],
        )

    async def _publish_ws_inbound(
        self,
        frame: dict[str, Any],
        text: str,
        *,
        files: list[dict[str, Any]] | None = None,
    ) -> None:
        if not self._ws_client:
            return
        try:
            from aibot import generate_req_id
        except Exception:
            return

        body = frame.get("body", {}) or {}
        msg_id = body.get("msgid")
        if not msg_id:
            return

        user_id = (body.get("from") or {}).get("userid")

        connect_code = self._pending_connect_code(text)
        if connect_code:
            handled = await self._bind_connection_from_connect_code(
                frame=frame,
                user_id=str(user_id or ""),
                code=connect_code,
            )
            if handled:
                return

        inbound_type = InboundMessageType.COMMAND if is_known_channel_command(text) else InboundMessageType.CHAT
        inbound = self._make_inbound(
            chat_id=user_id,  # keep user's conversation in memory
            user_id=user_id,
            text=text,
            msg_type=inbound_type,
            thread_ts=msg_id,
            files=files or [],
            metadata={
                "aibotid": body.get("aibotid"),
                "chattype": body.get("chattype"),
                "message_id": msg_id,
            },
        )
        inbound.topic_id = user_id  # keep the same thread

        stream_id = generate_req_id("stream")
        self._ws_frames[msg_id] = frame
        self._ws_stream_ids[msg_id] = stream_id

        reservation = self._reserve_inbound(inbound)
        if reservation is None:
            self._ws_frames.pop(msg_id, None)
            self._ws_stream_ids.pop(msg_id, None)
            return
        try:
            try:
                await self._ws_client.reply_stream(frame, stream_id, self._working_message, False)
            except Exception:
                pass

            inbound = await self._attach_connection_identity(inbound)
            self._commit_reserved_inbound(reservation, inbound)
        finally:
            reservation.release()

    async def _attach_connection_identity(self, inbound: InboundMessage) -> InboundMessage:
        return await attach_connection_identity(
            inbound,
            repo=self._connection_repo,
            provider="wecom",
            workspace_id=str(inbound.metadata.get("aibotid") or "") or None,
            fallback_without_workspace=True,
        )

    async def _bind_connection_from_connect_code(self, *, frame: dict[str, Any], user_id: str, code: str) -> bool:
        if self._connection_repo is None or not code:
            return False

        state = await self._connection_repo.consume_oauth_state(provider="wecom", state=code)
        if state is None:
            await self._send_connection_reply(frame, "WeCom connection code is invalid or expired.")
            return True

        if not user_id:
            await self._send_connection_reply(frame, "WeCom connection could not be completed from this message.")
            return True

        body = frame.get("body", {}) or {}
        workspace_id = str(body.get("aibotid") or "") or None
        await self._connection_repo.upsert_connection(
            owner_user_id=state["owner_user_id"],
            provider="wecom",
            external_account_id=user_id,
            workspace_id=workspace_id,
            metadata={
                "aibotid": workspace_id,
                "chattype": body.get("chattype"),
            },
            status="connected",
        )
        await self._send_connection_reply(frame, "WeCom connected to DeerFlow.")
        return True

    async def _send_connection_reply(self, frame: dict[str, Any], text: str) -> None:
        if not self._ws_client:
            return
        await self._ws_client.reply(frame, {"msgtype": "text", "text": {"content": text}})

    async def _send_ws(self, msg: OutboundMessage, *, _max_retries: int = 3) -> None:
        if not self._ws_client:
            return
        try:
            from aibot import generate_req_id
        except Exception:
            generate_req_id = None

        if msg.thread_ts and msg.thread_ts in self._ws_frames:
            frame = self._ws_frames[msg.thread_ts]
            stream_id = self._ws_stream_ids.get(msg.thread_ts)
            if not stream_id and generate_req_id:
                stream_id = generate_req_id("stream")
                self._ws_stream_ids[msg.thread_ts] = stream_id
            if not stream_id:
                return

            await self._send_with_retry(
                lambda: self._ws_client.reply_stream(frame, stream_id, msg.text, bool(msg.is_final)),
                max_retries=_max_retries,
                log_prefix="[WeCom]",
                operation_name="stream send",
            )
            return

        body = {"msgtype": "markdown", "markdown": {"content": msg.text}}
        await self._send_with_retry(
            lambda: self._ws_client.send_message(msg.chat_id, body),
            max_retries=_max_retries,
            log_prefix="[WeCom]",
        )

    async def _upload_media_ws(
        self,
        *,
        media_type: str,
        filename: str,
        path: str,
        size: int,
    ) -> str | None:
        if not self._ws_client:
            return None
        try:
            from aibot import generate_req_id
        except Exception:
            return None

        chunk_size = 512 * 1024
        total_chunks = (size + chunk_size - 1) // chunk_size
        if total_chunks < 1 or total_chunks > 100:
            logger.warning("[WeCom] invalid total_chunks=%d for %s", total_chunks, filename)
            return None

        md5 = await asyncio.to_thread(_file_md5, path)

        init_req_id = generate_req_id("aibot_upload_media_init")
        init_body = {
            "type": media_type,
            "filename": filename,
            "total_size": int(size),
            "total_chunks": int(total_chunks),
            "md5": md5,
        }
        init_ack = await self._send_ws_upload_command(init_req_id, init_body, "aibot_upload_media_init")
        upload_id = (init_ack.get("body") or {}).get("upload_id")
        if not upload_id:
            logger.warning("[WeCom] upload init returned no upload_id: %s", init_ack)
            return None

        file_obj = await asyncio.to_thread(_open_binary, path)
        try:
            for idx in range(total_chunks):
                data = await asyncio.to_thread(file_obj.read, chunk_size)
                if not data:
                    break
                chunk_req_id = generate_req_id("aibot_upload_media_chunk")
                chunk_body = {
                    "upload_id": upload_id,
                    "chunk_index": int(idx),
                    "base64_data": base64.b64encode(data).decode("utf-8"),
                }
                await self._send_ws_upload_command(chunk_req_id, chunk_body, "aibot_upload_media_chunk")
        finally:
            await asyncio.to_thread(file_obj.close)

        finish_req_id = generate_req_id("aibot_upload_media_finish")
        finish_ack = await self._send_ws_upload_command(finish_req_id, {"upload_id": upload_id}, "aibot_upload_media_finish")
        media_id = (finish_ack.get("body") or {}).get("media_id")
        if not media_id:
            logger.warning("[WeCom] upload finish returned no media_id: %s", finish_ack)
            return None
        return media_id

"""Browser session cookie policy for Gateway authentication."""

import logging
import os
from dataclasses import dataclass
from ipaddress import ip_address

from fastapi import Request, Response

from app.gateway.auth.config import get_auth_config
from app.gateway.auth.session_cookie_state import (
    SESSION_COOKIE_ISSUED_STATE_ATTR,
    SESSION_COOKIE_MAX_AGE_STATE_ATTR,
    SESSION_COOKIE_SECURE_STATE_ATTR,
)
from app.gateway.csrf_middleware import is_secure_request

ACCESS_TOKEN_COOKIE_NAME = "access_token"
SESSION_PERSISTENCE_COOKIE_NAME = "deerflow_session_persistent"
ALLOW_INSECURE_PERSISTENT_COOKIE_ENV = "DEER_FLOW_AUTH_ALLOW_INSECURE_PERSISTENT_COOKIE"

logger = logging.getLogger(__name__)


@dataclass(frozen=True)
class SessionCookiePolicy:
    """Resolved cookie settings for a session-creating auth response."""

    secure: bool
    max_age: int | None
    reason: str


def _env_flag_enabled(name: str) -> bool:
    return os.environ.get(name, "").strip().lower() in {"1", "true", "yes", "on"}


def _request_hostname(request: Request) -> str:
    """Return the direct request host without trusting forwarded host headers."""
    if request.url.hostname:
        return request.url.hostname.lower()
    return ""


def is_local_browser_origin(request: Request) -> bool:
    """Return True for loopback browser origins where HTTP persistence is acceptable."""
    host = _request_hostname(request)
    if host == "localhost" or host.endswith(".localhost"):
        return True
    try:
        return ip_address(host).is_loopback
    except ValueError:
        return False


def _remember_me_from_cookie(request: Request, *, default: bool) -> bool:
    value = request.cookies.get(SESSION_PERSISTENCE_COOKIE_NAME)
    if value == "1":
        return True
    if value == "0":
        return False
    return default


def resolve_session_cookie_policy(request: Request, *, remember_me: bool | None = None, default_remember_me: bool = True) -> SessionCookiePolicy:
    """Resolve session cookie settings from user intent and deployment context."""
    remember = _remember_me_from_cookie(request, default=default_remember_me) if remember_me is None else remember_me
    secure = is_secure_request(request)
    lifetime_seconds = get_auth_config().token_expiry_days * 24 * 3600

    if not remember:
        return SessionCookiePolicy(secure=secure, max_age=None, reason="session_requested")

    if secure:
        return SessionCookiePolicy(secure=True, max_age=lifetime_seconds, reason="secure_persistent")

    if is_local_browser_origin(request):
        return SessionCookiePolicy(secure=False, max_age=lifetime_seconds, reason="localhost_persistent")

    if _env_flag_enabled(ALLOW_INSECURE_PERSISTENT_COOKIE_ENV):
        return SessionCookiePolicy(secure=False, max_age=lifetime_seconds, reason="operator_insecure_persistent")

    return SessionCookiePolicy(secure=False, max_age=None, reason="public_http_session")


def set_session_cookie(response: Response, request: Request, token: str, *, remember_me: bool | None = None, default_remember_me: bool = True) -> SessionCookiePolicy:
    """Set the HttpOnly access-token cookie and stamp its lifetime on request state."""
    resolved_remember_me = _remember_me_from_cookie(request, default=default_remember_me) if remember_me is None else remember_me
    policy = resolve_session_cookie_policy(request, remember_me=resolved_remember_me, default_remember_me=default_remember_me)
    response.set_cookie(
        key=ACCESS_TOKEN_COOKIE_NAME,
        value=token,
        httponly=True,
        secure=policy.secure,
        samesite="lax",
        max_age=policy.max_age,
    )
    response.set_cookie(
        key=SESSION_PERSISTENCE_COOKIE_NAME,
        value="1" if resolved_remember_me else "0",
        httponly=True,
        secure=policy.secure,
        samesite="lax",
        max_age=policy.max_age,
    )
    setattr(request.state, SESSION_COOKIE_MAX_AGE_STATE_ATTR, policy.max_age)
    setattr(request.state, SESSION_COOKIE_SECURE_STATE_ATTR, policy.secure)
    setattr(request.state, SESSION_COOKIE_ISSUED_STATE_ATTR, True)
    logger.debug("Resolved auth session cookie policy: reason=%s secure=%s max_age=%s", policy.reason, policy.secure, policy.max_age)
    return policy

"""Shared browser-control capability checks for Gateway surfaces."""

from __future__ import annotations

import importlib.util
from dataclasses import dataclass
from typing import Any

from deerflow.community.browser_automation.session import browser_multi_worker_error
from deerflow.config.app_config import AppConfig


@dataclass(frozen=True)
class BrowserCapability:
    """Frontend/API availability for the agentic browser control surface."""

    configured: bool
    available: bool
    reason: str | None = None


def _tool_config(config: AppConfig) -> Any | None:
    get_tool_config = getattr(config, "get_tool_config", None)
    if callable(get_tool_config) and callable(getattr(type(config), "get_tool_config", None)):
        return get_tool_config("browser_navigate")
    return next(
        (tool for tool in (getattr(config, "tools", None) or []) if getattr(tool, "name", None) == "browser_navigate"),
        None,
    )


def _tool_extra(tool_cfg: Any) -> dict[str, Any]:
    extra = getattr(tool_cfg, "model_extra", None)
    return extra if isinstance(extra, dict) else {}


def browser_capability(config: AppConfig) -> BrowserCapability:
    """Return whether browser control can actually serve frontend requests."""

    tool_cfg = _tool_config(config)
    if tool_cfg is None:
        return BrowserCapability(configured=False, available=False, reason="browser_navigate is not configured")

    worker_error = browser_multi_worker_error()
    if worker_error is not None:
        return BrowserCapability(configured=True, available=False, reason=worker_error)

    extra = _tool_extra(tool_cfg)
    cdp_url = extra.get("cdp_url")
    if isinstance(cdp_url, str) and cdp_url.strip() and extra.get("allow_unguarded_cdp") is not True:
        return BrowserCapability(
            configured=True,
            available=False,
            reason="cdp_url requires allow_unguarded_cdp: true because DeerFlow cannot enforce the SSRF request guard on a CDP-attached browser",
        )

    if importlib.util.find_spec("playwright") is None or importlib.util.find_spec("playwright.async_api") is None:
        return BrowserCapability(
            configured=True,
            available=False,
            reason="Playwright is not installed; install the backend browser extra and run `playwright install chromium`",
        )

    return BrowserCapability(configured=True, available=True)


def ensure_browser_runtime_available(config: AppConfig) -> None:
    """Fail startup when browser control is configured but cannot run."""

    capability = browser_capability(config)
    if capability.configured and not capability.available:
        raise RuntimeError(capability.reason or "Browser automation is not available")

"""Shared helpers for resolving replay checkpoints on one checkpoint lineage."""

from __future__ import annotations

from collections.abc import Sequence
from typing import Any


class CheckpointLineageError(RuntimeError):
    """Raised when a requested checkpoint ancestor cannot be resolved safely."""


class CheckpointParentMissingError(CheckpointLineageError):
    """Raised when a legacy checkpoint does not record its parent link."""


class CheckpointLineageIntegrityError(CheckpointLineageError):
    """Raised when recorded checkpoint lineage is present but unsafe to use."""


def checkpoint_messages(checkpoint_tuple: Any) -> list[Any]:
    values = getattr(checkpoint_tuple, "values", None)
    if isinstance(values, dict):
        messages = values.get("messages", [])
        return list(messages) if isinstance(messages, list) else []
    checkpoint = getattr(checkpoint_tuple, "checkpoint", None) or {}
    channel_values = checkpoint.get("channel_values", {}) if isinstance(checkpoint, dict) else {}
    messages = channel_values.get("messages", []) if isinstance(channel_values, dict) else []
    return list(messages) if isinstance(messages, list) else []


def checkpoint_configurable(checkpoint_tuple: Any) -> dict[str, Any]:
    config = getattr(checkpoint_tuple, "config", None) or {}
    configurable = config.get("configurable", {}) if isinstance(config, dict) else {}
    return dict(configurable) if isinstance(configurable, dict) else {}


def checkpoint_metadata(checkpoint_tuple: Any) -> dict[str, Any]:
    metadata = getattr(checkpoint_tuple, "metadata", None) or {}
    return dict(metadata) if isinstance(metadata, dict) else {}


def is_duration_only_checkpoint(checkpoint_tuple: Any) -> bool:
    writes = checkpoint_metadata(checkpoint_tuple).get("writes")
    return isinstance(writes, dict) and "runtime_run_duration" in writes


def has_pending_tasks(checkpoint_tuple: Any) -> bool:
    """Return whether *checkpoint_tuple* still has graph work scheduled.

    A replay base must be a state the thread was at rest in. A mid-run
    checkpoint owns the writes of the node that was about to run, and resuming
    from it replays them — re-adding the very turn the replay is meant to
    replace. Message ids alone cannot detect this, because middleware may
    rewrite a message's id in the same run that produced it.

    ``next`` is not derivable on the degraded raw-checkpoint read path, which
    reports no tasks at all. Absence of evidence therefore stays permissive:
    those reads keep selecting the same base they always did.
    """

    return bool(getattr(checkpoint_tuple, "next", None))


def _message_id(message: Any) -> str | None:
    value = getattr(message, "id", None)
    if value is None and isinstance(message, dict):
        value = message.get("id")
    return str(value) if value else None


def _config_identity(config: dict[str, Any]) -> tuple[str, str, str] | None:
    configurable = config.get("configurable", {})
    thread_id = configurable.get("thread_id")
    checkpoint_ns = configurable.get("checkpoint_ns", "")
    checkpoint_id = configurable.get("checkpoint_id")
    if not isinstance(thread_id, str) or not thread_id or not isinstance(checkpoint_id, str) or not checkpoint_id:
        return None
    return thread_id, str(checkpoint_ns or ""), checkpoint_id


def _checkpoint_identity(checkpoint_tuple: Any) -> tuple[str, str, str] | None:
    return _config_identity(getattr(checkpoint_tuple, "config", {}) or {})


def _checkpoint_exists(checkpoint_tuple: Any) -> bool:
    """Distinguish a persisted empty checkpoint from an accessor miss.

    LangGraph represents a missing explicit ``checkpoint_id`` as an empty
    snapshot that echoes the requested config. Persisted snapshots always
    carry metadata, a creation timestamp, or a raw checkpoint payload.
    """

    explicit = getattr(checkpoint_tuple, "checkpoint_exists", None)
    if isinstance(explicit, bool):
        return explicit
    if getattr(checkpoint_tuple, "metadata", None) is not None:
        return True
    if getattr(checkpoint_tuple, "created_at", None) is not None:
        return True
    return isinstance(getattr(checkpoint_tuple, "checkpoint", None), dict)


async def find_checkpoint_before_message(
    accessor: Any,
    head_checkpoint: Any,
    message_id: str,
    *,
    max_depth: int,
) -> Any:
    """Walk one parent lineage and return the first checkpoint before ``message_id``.

    Following ``parent_config`` is important after a regenerate: a thread can contain
    sibling checkpoint branches, and a global time-ordered scan can otherwise select
    a checkpoint from the wrong branch. Duration-only metadata checkpoints do not
    represent an addressable conversation state and are skipped, and so are
    checkpoints that still have pending tasks (see :func:`has_pending_tasks`).
    """

    if message_id not in {_message_id(message) for message in checkpoint_messages(head_checkpoint)}:
        raise CheckpointLineageIntegrityError("Target message is not present in the checkpoint head")

    current = head_checkpoint
    visited: set[tuple[str, str, str]] = set()
    current_identity = _checkpoint_identity(current)
    if current_identity is not None:
        visited.add(current_identity)

    # Each step performs one ancestor read, but normal branch/regenerate
    # histories cross the target boundary within 1–3 reads. Keep max_depth as
    # a conservative safety cap for valid histories with many intermediate or
    # duration-only checkpoints.
    for _ in range(max_depth):
        parent_config = getattr(current, "parent_config", None)
        if not isinstance(parent_config, dict):
            raise CheckpointParentMissingError("Checkpoint lineage ended before the target message")

        parent = await accessor.aget(parent_config)
        parent_identity = _checkpoint_identity(parent)
        requested_parent_identity = _config_identity(parent_config)
        if parent_identity is None or not _checkpoint_exists(parent) or (requested_parent_identity is not None and parent_identity != requested_parent_identity):
            raise CheckpointLineageIntegrityError("Checkpoint parent link is not addressable")
        if parent_identity is not None:
            if parent_identity in visited:
                raise CheckpointLineageIntegrityError("Checkpoint lineage contains a cycle")
            visited.add(parent_identity)

        if is_duration_only_checkpoint(parent):
            current = parent
            continue

        parent_message_ids = {_message_id(message) for message in checkpoint_messages(parent)}
        if message_id not in parent_message_ids and not has_pending_tasks(parent):
            return parent
        current = parent

    raise CheckpointLineageIntegrityError(f"Checkpoint lineage exceeded the scan limit ({max_depth})")


def find_checkpoint_before_message_chronologically(
    checkpoints: Sequence[Any],
    message_id: str,
) -> tuple[Any | None, bool]:
    """Return ``(replay_base, target_found)`` from newest-first history.

    This is a compatibility fallback for imported or legacy checkpoints that do
    not carry ``parent_config`` links. Callers must prefer the lineage walk when
    links are available because a chronological scan cannot distinguish sibling
    checkpoint branches. Duration-only checkpoints are ignored, and only settled
    checkpoints (see :func:`has_pending_tasks`) with an addressable id can become
    the replay base.
    """

    previous_checkpoint = None
    for checkpoint_tuple in reversed(checkpoints):
        if is_duration_only_checkpoint(checkpoint_tuple):
            continue
        message_ids = {_message_id(message) for message in checkpoint_messages(checkpoint_tuple)}
        if message_id in message_ids:
            return previous_checkpoint, True
        if checkpoint_configurable(checkpoint_tuple).get("checkpoint_id") and not has_pending_tasks(checkpoint_tuple):
            previous_checkpoint = checkpoint_tuple
    return None, False

"""Compute the current message-context usage for a thread."""

from __future__ import annotations

import asyncio
import logging
from typing import Any

from fastapi import HTTPException, Request

from app.gateway.deps import get_config
from app.gateway.services import build_thread_checkpoint_state_accessor

logger = logging.getLogger(__name__)


def _count_messages_approximately(messages: list[Any]) -> int:
    """Count checkpoint messages with LangChain's network-free heuristic."""
    if not messages:
        return 0
    from langchain_core.messages.utils import count_tokens_approximately

    return int(count_tokens_approximately(messages))


async def _load_checkpoint_messages(accessor: Any, config: dict[str, Any]) -> list[Any]:
    """Read materialized messages so full and delta checkpoints behave alike."""
    snapshot = await accessor.aget(config)
    values = getattr(snapshot, "values", None) or {}
    if not isinstance(values, dict):
        return []
    return list(values.get("messages") or [])


async def _resolve_thread_model_name(run_store: Any, thread_id: str, app_config: Any) -> str | None:
    """Prefer the latest run's model, then fall back to the first configured model."""
    try:
        runs = await run_store.list_by_thread(thread_id, limit=1)
    except Exception:
        runs = []
    if runs:
        latest = runs[0]
        name = latest.get("model_name") if isinstance(latest, dict) else getattr(latest, "model_name", None)
        if isinstance(name, str) and name:
            return name
    models = getattr(app_config, "models", None) or []
    return models[0].name if models else None


def build_context_usage_payload(*, token_count: int, max_context_tokens: int | None) -> dict[str, Any]:
    """Build the stable API payload for a message count and model capacity."""
    percentage: float | None = None
    if max_context_tokens and max_context_tokens > 0:
        percentage = round(token_count / max_context_tokens * 100, 1)
    return {
        "token_count": token_count,
        "max_context_tokens": max_context_tokens,
        "percentage": percentage,
    }


async def build_context_usage(request: Request, thread_id: str, run_store: Any) -> dict[str, Any] | None:
    """Return approximate usage for the latest materialized thread checkpoint."""
    try:
        app_config = get_config()
    except HTTPException:
        return None

    try:
        accessor, checkpoint_config = await build_thread_checkpoint_state_accessor(request, thread_id=thread_id)
        messages = await _load_checkpoint_messages(accessor, checkpoint_config)
    except Exception:
        logger.warning("Failed to load checkpoint for context usage on thread %s", thread_id, exc_info=True)
        return None

    try:
        token_count = await asyncio.to_thread(_count_messages_approximately, messages)
    except Exception:
        logger.warning("Failed to count context messages for thread %s", thread_id, exc_info=True)
        return None

    model_name = await _resolve_thread_model_name(run_store, thread_id, app_config)
    model_config = app_config.get_model_config(model_name) if model_name else None
    configured_window = getattr(model_config, "context_window", None) if model_config is not None else None
    max_context_tokens = int(configured_window) if configured_window else None
    return build_context_usage_payload(token_count=token_count, max_context_tokens=max_context_tokens)

"""Shared pagination helpers for gateway routers."""

from __future__ import annotations


def trim_run_message_page(rows: list[dict], *, limit: int, after_seq: int | None) -> tuple[list[dict], bool]:
    """Trim a ``limit + 1`` run-message page while preserving page boundaries."""
    has_more = len(rows) > limit
    if not has_more:
        return rows, False

    if after_seq is not None:
        return rows[:limit], True

    return rows[-limit:], True

