def get_thread_state_schema(mode: CheckpointChannelMode, snapshot_frequency: int | None = None) -> type:
    if mode != "delta":
        return ThreadState
    return _delta_thread_state_schema(_resolve_snapshot_frequency(snapshot_frequency))


@cache
def _delta_thread_state_schema(snapshot_frequency: int) -> type:
    """Delta thread schema keyed by cadence; the default keeps the static
    ``DeltaThreadState`` identity so existing type checks keep holding."""
    if snapshot_frequency == DEFAULT_CHECKPOINT_SNAPSHOT_FREQUENCY:
        return DeltaThreadState
    annotations = get_type_hints(ThreadState, include_extras=True)
    annotations["messages"] = delta_messages_field(snapshot_frequency)
    return TypedDict(
        f"DeltaThreadState_f{snapshot_frequency}",
        annotations,
        total=getattr(ThreadState, "__total__", True),
    )


def adapt_state_schema_for_mode(schema: type, mode: CheckpointChannelMode, snapshot_frequency: int | None = None) -> type:
    if mode == "full":
        return schema
    return _adapt_state_schema_for_delta(schema, _resolve_snapshot_frequency(snapshot_frequency))


@cache
def _adapt_state_schema_for_delta(schema: type, snapshot_frequency: int) -> type:
    annotations = get_type_hints(schema, include_extras=True)
    annotations["messages"] = delta_messages_field(snapshot_frequency)
    return TypedDict(
        f"Delta{schema.__module__.replace('.', '_')}_{schema.__name__}_f{snapshot_frequency}",
        annotations,
        total=getattr(schema, "__total__", True),
    )


def normalize_middleware_state_schemas(middleware: Sequence[Any], mode: CheckpointChannelMode, snapshot_frequency: int | None = None) -> list[Any]:
    if mode == "full":
        return list(middleware)
    resolved_frequency = _resolve_snapshot_frequency(snapshot_frequency)
    normalized = []
    for item in middleware:
        schema = getattr(item, "state_schema", None)
        if schema is None:
            normalized.append(item)
            continue
        adapted = copy.copy(item)
        adapted.state_schema = adapt_state_schema_for_mode(schema, mode, resolved_frequency)
        normalized.append(adapted)
    return normalized

"""Built-in RBAC authorization provider.

Reads a role→resource policy from config and compiles it into immutable
structures at construction time. Deny always wins over allow. Unknown or
missing roles raise ``ValueError`` (not a silent allow) so that the execution
layer's ``fail_closed`` can make the final decision.

See ``docs/plans/2026-07-15-authz-phase1a-implementation-plan.md`` §3.3 for
the full semantic table.
"""

from __future__ import annotations

from typing import Any

from deerflow.authz.provider import (
    AuthzDecision,
    AuthzReason,
    AuthzRequest,
    Principal,
)

# Explicit resource-type → config-key mapping. Prevents silent mis-lookup
# when ``AuthzRequest.resource`` (singular, e.g. "tool") doesn't match the
# config key (plural, e.g. "tools").
_RESOURCE_POLICY_KEYS: dict[str, str] = {
    "tool": "tools",
    "model": "models",
    "skill": "skills",
    "sandbox": "sandbox",
    "mcp_server": "mcp_servers",
    "route": "routes",
}

_ALL = object()  # sentinel meaning "allow all candidates"
_ABSENT = object()  # sentinel meaning "key not present in dict"


# The only supported keys in a resource policy dict. Any other key (typos,
# unknown fields) is rejected at construction to prevent silent mis-grants.
_SUPPORTED_POLICY_KEYS: frozenset[str] = frozenset({"allow", "deny"})


def _require_non_empty_string(value: object, *, field: str) -> str:
    """Return a validated request identifier or raise a stable boundary error."""
    if not isinstance(value, str) or not value:
        raise ValueError(f"{field} must be a non-empty string, got {value!r}")
    return value


class _CompiledPolicy:
    """Immutable, pre-validated policy for a single (role, resource_type) pair."""

    __slots__ = ("allowed", "denied")

    def __init__(self, *, allowed: frozenset[str] | object, denied: frozenset[str]):
        self.allowed = allowed
        self.denied = denied

    def is_allowed(self, target: str) -> bool:
        # Deny always wins.
        if target in self.denied:
            return False
        if self.allowed is _ALL:
            return True
        return target in self.allowed


class RbacAuthorizationProvider:
    """Built-in role-based authorization provider.

    Configured via ``roles`` mapping where each role maps resource-type keys
    to ``{allow: ..., deny: [...]}`` policies. Policy configuration is fully
    validated at construction; the request path validates identifiers before
    performing membership checks.

    Policies are scoped by role, resource, and target. ``AuthzRequest.action``
    is accepted for protocol compatibility but is not a rule dimension in this
    built-in provider.

    Example config::

        roles:
          admin:
            tools: {allow: "*"}
          user:
            tools: {allow: "*", deny: ["update_agent"]}
          guest:
            tools: {allow: ["web_search", "read_file"]}
    """

    name = "rbac"

    def __init__(self, *, roles: dict[str, Any] | object = _ABSENT, **kwargs: Any) -> None:
        if kwargs:
            raise ValueError(f"unknown provider config keys {sorted(kwargs, key=repr)}; supported: ['roles']")
        if roles is _ABSENT:
            raise ValueError("missing required provider config key 'roles'")
        if not isinstance(roles, dict):
            raise ValueError(f"roles must be a dict, got {type(roles).__name__}")

        # Compile all policies up front.
        self._policies: dict[tuple[str, str], _CompiledPolicy] = {}
        self._known_roles: frozenset[str] = frozenset(roles.keys())

        for role_name, role_config in roles.items():
            if not isinstance(role_name, str) or not role_name:
                raise ValueError(f"role name must be a non-empty string, got {role_name!r}")
            if not isinstance(role_config, dict):
                raise ValueError(f"role '{role_name}' config must be a dict, got {type(role_config).__name__}")

            for resource_key, resource_policy in role_config.items():
                if not isinstance(resource_key, str) or not resource_key:
                    raise ValueError(f"role '{role_name}' has invalid resource key {resource_key!r}")
                mapped_resource_key = _RESOURCE_POLICY_KEYS.get(resource_key)
                if mapped_resource_key is not None and mapped_resource_key != resource_key:
                    raise ValueError(f"role '{role_name}' resource key '{resource_key}' is a reserved request alias; use '{mapped_resource_key}' in RBAC config")
                if not isinstance(resource_policy, dict):
                    raise ValueError(f"role '{role_name}' resource '{resource_key}' must be a dict, got {type(resource_policy).__name__}")

                compiled = self._compile_resource_policy(role_name, resource_key, resource_policy)
                self._policies[(role_name, resource_key)] = compiled

    def validate_role(self, role: str, *, field: str = "role") -> None:
        """Fail fast when an operator-configured role is not defined."""
        role = _require_non_empty_string(role, field=field)
        if role not in self._known_roles:
            if field == "role":
                raise ValueError(f"Unknown role '{role}'; known roles: {sorted(self._known_roles)}")
            raise ValueError(f"{field} '{role}' is not defined; known roles: {sorted(self._known_roles)}")

    @staticmethod
    def _compile_resource_policy(
        role_name: str,
        resource_key: str,
        policy: dict[str, Any],
    ) -> _CompiledPolicy:
        """Validate and compile a single resource policy into immutable structures.

        Distinguishes "key absent" (use default) from "key present but null"
        (invalid — reject). Unknown keys (typos) are rejected to prevent
        silent mis-grants.
        """
        # --- reject unknown keys (catch typos like "alow") ---
        unknown_keys = set(policy.keys()) - _SUPPORTED_POLICY_KEYS
        if unknown_keys:
            raise ValueError(f"role '{role_name}' resource '{resource_key}': unknown policy keys {sorted(unknown_keys, key=repr)}; supported: {sorted(_SUPPORTED_POLICY_KEYS)}")

        # --- allow ---
        raw_allow = policy.get("allow", _ABSENT)
        if raw_allow is _ABSENT:
            allowed: frozenset[str] | object = _ALL  # missing allow = allow all (deny still applies)
        elif raw_allow is None:
            raise ValueError(f"role '{role_name}' resource '{resource_key}': allow must not be null; omit the key, or use '*' / bool / list")
        elif raw_allow is True:
            allowed = _ALL
        elif raw_allow is False:
            allowed = frozenset()  # allow: false = deny all
        elif isinstance(raw_allow, str):
            if raw_allow == "*":
                allowed = _ALL
            else:
                raise ValueError(f"role '{role_name}' resource '{resource_key}': allow string must be '*', got {raw_allow!r}")
        elif isinstance(raw_allow, (list, tuple)):
            for item in raw_allow:
                if not isinstance(item, str) or not item:
                    raise ValueError(f"role '{role_name}' resource '{resource_key}': allow list contains non-string or empty item {item!r}")
            allowed = frozenset(raw_allow)
        else:
            raise ValueError(f"role '{role_name}' resource '{resource_key}': allow must be '*', bool, or list of strings, got {type(raw_allow).__name__}")

        # --- deny ---
        raw_deny = policy.get("deny", _ABSENT)
        if raw_deny is _ABSENT or raw_deny is None:
            if raw_deny is None:
                raise ValueError(f"role '{role_name}' resource '{resource_key}': deny must not be null; omit the key for no deny list")
            denied: frozenset[str] = frozenset()
        elif isinstance(raw_deny, (list, tuple)):
            for item in raw_deny:
                if not isinstance(item, str) or not item:
                    raise ValueError(f"role '{role_name}' resource '{resource_key}': deny list contains non-string or empty item {item!r}")
            denied = frozenset(raw_deny)
        else:
            raise ValueError(f"role '{role_name}' resource '{resource_key}': deny must be a list of strings, got {type(raw_deny).__name__}")

        return _CompiledPolicy(allowed=allowed, denied=denied)

    def _resolve_policy(
        self,
        principal: Principal,
        resource: str,
        *,
        resource_field: str = "resource",
    ) -> _CompiledPolicy | None:
        """Look up the compiled policy for (role, resource_type).

        Returns ``None`` if no policy is configured for this role+resource
        (meaning: unrestricted). Raises ``ValueError`` for invalid resource
        identifiers and unknown or missing roles.
        """
        role = principal.role
        if role is None or role == "":
            raise ValueError("Principal has no role; cannot evaluate RBAC policy")

        self.validate_role(role)

        resource = _require_non_empty_string(resource, field=resource_field)
        resource_key = _RESOURCE_POLICY_KEYS.get(resource, resource)
        return self._policies.get((role, resource_key))

    def authorize(self, request: AuthzRequest) -> AuthzDecision:
        """Evaluate a single authorization request."""
        policy = self._resolve_policy(request.principal, request.resource)
        target = _require_non_empty_string(request.target, field="target")
        if policy is None:
            # No policy for this role+resource → unrestricted.
            return AuthzDecision(
                allow=True,
                reasons=[AuthzReason(code="authz.no_policy", message="no policy configured")],
                policy_id="rbac:unrestricted",
            )

        if policy.is_allowed(target):
            return AuthzDecision(
                allow=True,
                reasons=[AuthzReason(code="authz.allowed")],
                policy_id="rbac:allow",
            )
        return AuthzDecision(
            allow=False,
            reasons=[
                AuthzReason(
                    code="authz.denied",
                    message=f"role '{request.principal.role}' is denied '{target}' on resource '{request.resource}'",
                )
            ],
            policy_id="rbac:deny",
        )

    async def aauthorize(self, request: AuthzRequest) -> AuthzDecision:
        return self.authorize(request)

    def filter_resources(
        self,
        principal: Principal,
        resource_type: str,
        candidates: list[str],
    ) -> list[str]:
        """Batch visibility filter.

        Preserves candidate order and duplicates, never adds items, and raises
        the same role/resource errors as :meth:`authorize`.
        """
        policy = self._resolve_policy(principal, resource_type, resource_field="resource_type")
        if not isinstance(candidates, list):
            raise ValueError(f"candidates must be a list, got {type(candidates).__name__}")
        validated_candidates = [_require_non_empty_string(candidate, field=f"candidates[{index}]") for index, candidate in enumerate(candidates)]
        if policy is None:
            return validated_candidates

        return [candidate for candidate in validated_candidates if policy.is_allowed(candidate)]

"""Provider factory — discovers and constructs the configured provider.

The two-phase API lets async callers offload class-path discovery/import while
constructing loop-affine providers on their running event loop. The synchronous
``resolve_authorization_provider`` convenience function composes both phases.
Instances are not cached (Phase 1B resolves once per agent build and passes the
same instance to Layer 1 and Layer 2).
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any

from deerflow.authz.provider import AuthorizationProvider
from deerflow.config.authorization_config import AuthorizationConfig
from deerflow.reflection import resolve_variable


@dataclass(frozen=True, slots=True)
class AuthorizationProviderSpec:
    """A discovered provider class and its constructor inputs."""

    class_path: str
    provider_cls: type[Any]
    kwargs: dict[str, Any]


def resolve_authorization_provider_spec(
    config: AuthorizationConfig,
) -> AuthorizationProviderSpec | None:
    """Discover a provider class without constructing the provider.

    Returns:
        Constructor inputs for the configured provider, or ``None`` if
        authorization is disabled. This discovery phase may import a custom
        module and is safe to offload from an async event loop.

    Raises:
        ValueError: If ``enabled`` is True but no provider is configured,
            or if the class path is invalid.
    """
    if not config.enabled:
        return None

    if config.provider is None:
        raise ValueError("authorization.enabled is true but no provider is configured; set authorization.provider.use to a class path")

    class_path = config.provider.use
    try:
        provider_cls = resolve_variable(class_path, expected_type=type)
    except (ImportError, ValueError) as err:
        raise ValueError(f"Failed to resolve authorization provider class '{class_path}': {err}") from err

    kwargs = dict(config.provider.config) if config.provider.config else {}
    return AuthorizationProviderSpec(class_path=class_path, provider_cls=provider_cls, kwargs=kwargs)


def construct_authorization_provider(
    spec: AuthorizationProviderSpec | None,
    config: AuthorizationConfig,
) -> AuthorizationProvider | None:
    """Construct and validate a previously discovered provider spec."""
    if spec is None:
        return None

    try:
        instance = spec.provider_cls(**spec.kwargs)
    except Exception as err:
        raise ValueError(f"Failed to construct authorization provider '{spec.class_path}': {err}") from err

    if not isinstance(instance, AuthorizationProvider):
        raise ValueError(f"Authorization provider '{spec.class_path}' does not satisfy the AuthorizationProvider Protocol")

    from deerflow.authz.rbac import RbacAuthorizationProvider

    if isinstance(instance, RbacAuthorizationProvider):
        try:
            instance.validate_role(config.default_role, field="authorization.default_role")
        except ValueError as err:
            raise ValueError(f"Invalid authorization default_role for provider '{spec.class_path}': {err}") from err

    return instance


def resolve_authorization_provider(
    config: AuthorizationConfig,
) -> AuthorizationProvider | None:
    """Discover, construct, and validate the configured provider synchronously."""
    return construct_authorization_provider(resolve_authorization_provider_spec(config), config)

"""
Web and image search tools powered by the Brave Search API.

Brave Search provides web and image results from an independent search index
via a REST API. An API key is required. Sign up at
https://brave.com/search/api/ to get one.

Unlike the DuckDuckGo ``backend: brave`` option (which scrapes results via the
DDGS aggregator), this provider calls the official Brave Search API directly,
giving structured results, authenticated quota, and a documented SLA.
"""

import json
import logging
import os
from ipaddress import IPv4Address, IPv6Address, ip_address, ip_network
from urllib.parse import urlparse

import httpx
from langchain.tools import tool

from deerflow.community.search_time_range import BRAVE_FRESHNESS_BY_TIME_RANGE, SearchTimeRange
from deerflow.config import get_app_config

logger = logging.getLogger(__name__)

_BRAVE_WEB_ENDPOINT = "https://api.search.brave.com/res/v1/web/search"
_BRAVE_IMAGES_ENDPOINT = "https://api.search.brave.com/res/v1/images/search"
_DEFAULT_MAX_RESULTS = 5
# Brave Search API caps the `count` parameter at 20 results per request.
_BRAVE_WEB_MAX_COUNT = 20
# Brave Image Search supports larger batches than web search.
_BRAVE_IMAGE_MAX_COUNT = 200
# NAT64 well-known prefix (RFC 6052): IPv6 literals embedding an IPv4 address.
_NAT64_PREFIX = ip_network("64:ff9b::/96")
_api_key_warned: set[str] = set()


def _get_api_key(tool_name: str = "web_search") -> str | None:
    config = get_app_config().get_tool_config(tool_name)
    if config is not None:
        api_key = (config.model_extra or {}).get("api_key")
        if isinstance(api_key, str) and api_key.strip():
            return api_key.strip()
    env_key = os.getenv("BRAVE_SEARCH_API_KEY")
    if isinstance(env_key, str) and env_key.strip():
        return env_key.strip()
    return None


def _coerce_max_results(
    value: object,
    *,
    default: int = _DEFAULT_MAX_RESULTS,
    max_allowed: int = _BRAVE_WEB_MAX_COUNT,
) -> int:
    try:
        coerced = int(value)
    except (TypeError, ValueError):
        logger.warning(
            "Invalid Brave Search max_results=%r; using default %s",
            value,
            default,
        )
        coerced = default

    return max(1, min(coerced, max_allowed))


def _clean_query(query: str, *, max_length: int = 400) -> str:
    query = query.strip()
    if len(query) > max_length:
        query = query[:max_length]
    return query


def _missing_key_error(query: str, tool_name: str) -> str:
    if tool_name not in _api_key_warned:
        _api_key_warned.add(tool_name)
        logger.warning(
            "Brave Search API key is not set for '%s'. Set BRAVE_SEARCH_API_KEY in your environment or provide api_key in config.yaml. Sign up at https://brave.com/search/api/",
            tool_name,
        )
    return json.dumps(
        {"error": "BRAVE_SEARCH_API_KEY is not configured", "query": query},
        ensure_ascii=False,
    )


def _unexpected_format_error(query: str, *, service_name: str = "Brave Search") -> str:
    return json.dumps(
        {"error": f"{service_name} returned an unexpected response format", "query": query},
        ensure_ascii=False,
    )


def _decode_ipv4(host: str) -> IPv4Address | None:
    """Decode obfuscated IPv4 literals that ``ip_address`` rejects.

    Mirrors the permissive ``inet_aton`` parsing many HTTP clients use, so that
    integer (``2130706433``), hex (``0x7f000001``) and octal (``0177.0.0.1``)
    encodings of an address are recognized.
    """
    parts = host.split(".")
    if not 1 <= len(parts) <= 4:
        return None

    values: list[int] = []
    for part in parts:
        if not part:
            return None
        try:
            if part.startswith(("0x", "0X")):
                values.append(int(part, 16))
            elif part.startswith("0") and len(part) > 1:
                values.append(int(part, 8))
            else:
                values.append(int(part, 10))
        except ValueError:
            return None

    *leading, last = values
    for value in leading:
        if not 0 <= value <= 0xFF:
            return None
    max_last = (1 << (8 * (4 - len(leading)))) - 1
    if not 0 <= last <= max_last:
        return None

    result = 0
    for value in leading:
        result = (result << 8) | value
    result = (result << (8 * (4 - len(leading)))) | last
    return IPv4Address(result)


def _is_url_present(value: object) -> bool:
    return isinstance(value, str) and bool(value.strip())


def _embedded_ipv4(ip: IPv6Address) -> IPv4Address | None:
    """Extract an IPv4 address embedded in an IPv6 literal, if any.

    Covers IPv4-mapped (``::ffff:a.b.c.d``), 6to4 (``2002::/16``), NAT64
    (``64:ff9b::/96``), and IPv4-compatible (``::a.b.c.d``) forms. These all
    smuggle a v4 destination through the IPv6 path, where ``is_global`` on the
    v6 literal alone would otherwise report a loopback/private target as safe.
    """
    if ip.ipv4_mapped is not None:
        return ip.ipv4_mapped
    if ip.sixtofour is not None:
        return ip.sixtofour
    if ip in _NAT64_PREFIX:
        return IPv4Address(int(ip) & 0xFFFFFFFF)
    # IPv4-compatible ``::a.b.c.d`` (high 96 bits zero, excluding ::/:: 1).
    packed = int(ip)
    if packed >> 32 == 0 and packed > 1:
        return IPv4Address(packed & 0xFFFFFFFF)
    return None


def _safe_public_url(value: object) -> str:
    """Return ``value`` only if it is a safe, public http(s) URL, else "".

    This is a best-effort SSRF guard that rejects non-http(s) schemes,
    ``localhost``, and private/non-global IP literals (including obfuscated
    decimal/hex/octal encodings and IPv6 literals embedding a non-global IPv4).
    It only inspects the URL string and cannot catch public hostnames that
    resolve to internal IPs; any consumer that actually downloads these URLs
    must re-validate the resolved IP at fetch time.
    """
    if not isinstance(value, str):
        return ""
    url = value.strip()
    try:
        parsed = urlparse(url)
    except ValueError:
        return ""
    if parsed.scheme not in {"http", "https"} or not parsed.netloc or not parsed.hostname:
        return ""

    host = parsed.hostname.lower().rstrip(".")
    if not host:
        return ""
    if host == "localhost" or host.endswith(".localhost"):
        return ""

    try:
        ip = ip_address(host)
    except ValueError:
        ip = _decode_ipv4(host)
        if ip is None:
            return url
    if isinstance(ip, IPv6Address):
        embedded = _embedded_ipv4(ip)
        if embedded is not None and not embedded.is_global:
            return ""
    return url if ip.is_global else ""


def _brave_get(
    endpoint: str,
    api_key: str,
    query: str,
    params: dict[str, object],
    *,
    service_name: str,
) -> tuple[dict | None, str | None]:
    headers = {
        "X-Subscription-Token": api_key,
        "Accept": "application/json",
    }
    try:
        with httpx.Client(timeout=30) as client:
            response = client.get(endpoint, headers=headers, params=params)
        response.raise_for_status()
        data = response.json()
        if not isinstance(data, dict):
            logger.error("%s returned an unexpected payload type: %s", service_name, type(data).__name__)
            return None, _unexpected_format_error(query, service_name=service_name)
        return data, None
    except httpx.HTTPStatusError as e:
        logger.error("%s API returned HTTP %s: %s", service_name, e.response.status_code, e.response.text)
        return None, json.dumps(
            {"error": f"{service_name} API error: HTTP {e.response.status_code}", "query": query},
            ensure_ascii=False,
        )
    except Exception as e:
        logger.error("%s request failed: %s: %s", service_name, type(e).__name__, e)
        return None, json.dumps({"error": str(e), "query": query}, ensure_ascii=False)


@tool("web_search", parse_docstring=True)
def web_search_tool(query: str, max_results: int = 5, time_range: SearchTimeRange | None = None) -> str:
    """Search the web for information using Brave Search.

    Args:
        query: Search keywords describing what you want to find. Be specific for better results.
        max_results: Maximum number of search results to return. Default is 5.
        time_range: Optional relative publication/update window. Use only when the request requires recent results.
    """
    config = get_app_config().get_tool_config("web_search")
    if config is not None and "max_results" in (config.model_extra or {}):
        max_results = config.model_extra["max_results"]

    count = _coerce_max_results(max_results, max_allowed=_BRAVE_WEB_MAX_COUNT)
    query = _clean_query(query)

    api_key = _get_api_key("web_search")
    if not api_key:
        return _missing_key_error(query, "web_search")

    params = {"q": query, "count": count, "text_decorations": False}
    if time_range is not None:
        params["freshness"] = BRAVE_FRESHNESS_BY_TIME_RANGE[time_range]

    data, error_json = _brave_get(_BRAVE_WEB_ENDPOINT, api_key, query, params, service_name="Brave Search")
    if error_json is not None:
        return error_json

    web_results = (data.get("web") or {}).get("results", [])
    if not web_results:
        return json.dumps({"error": "No results found", "query": query}, ensure_ascii=False)

    normalized_results = [
        {
            "title": r.get("title", ""),
            "url": r.get("url", ""),
            "content": r.get("description", ""),
        }
        for r in web_results
    ]

    output = {
        "query": query,
        "total_results": len(normalized_results),
        "results": normalized_results,
    }
    return json.dumps(output, indent=2, ensure_ascii=False)


@tool("image_search", parse_docstring=True)
def image_search_tool(query: str, max_results: int = 5) -> str:
    """Search for images online using Brave Image Search. Use this tool BEFORE image generation to find reference images for characters, portraits, objects, scenes, or any content requiring visual accuracy.

    The returned image URLs can be used as reference images in image generation to significantly improve quality.

    Args:
        query: Search keywords describing the images you want to find. Be specific for better results.
        max_results: Maximum number of images to return. Default is 5, capped at 200.
    """
    config = get_app_config().get_tool_config("image_search")
    extra = (config.model_extra or {}) if config is not None else {}
    if "max_results" in extra:
        max_results = extra["max_results"]
    count = _coerce_max_results(max_results, max_allowed=_BRAVE_IMAGE_MAX_COUNT)
    query = _clean_query(query)

    api_key = _get_api_key("image_search")
    if not api_key:
        return _missing_key_error(query, "image_search")

    params: dict[str, object] = {"q": query, "count": count}
    for key in ("country", "search_lang", "safesearch", "spellcheck"):
        if key in extra:
            params[key] = extra[key]

    data, error_json = _brave_get(
        _BRAVE_IMAGES_ENDPOINT,
        api_key,
        query,
        params,
        service_name="Brave Image Search",
    )
    if error_json is not None:
        return error_json

    images = data.get("results")
    if images is None:
        images = []
    if not isinstance(images, list):
        logger.error("Brave Image Search returned unexpected 'results' payload type: %s", type(images).__name__)
        return _unexpected_format_error(query, service_name="Brave Image Search")
    if not images:
        return json.dumps({"error": "No images found", "query": query}, ensure_ascii=False)

    normalized_results = []
    for item in images:
        if not isinstance(item, dict):
            continue
        thumbnail = item.get("thumbnail") if isinstance(item.get("thumbnail"), dict) else {}
        properties = item.get("properties") if isinstance(item.get("properties"), dict) else {}
        raw_image = properties.get("url")
        raw_thumb = thumbnail.get("src")
        raw_source = item.get("url")

        safe_image = _safe_public_url(raw_image)
        safe_thumb = _safe_public_url(raw_thumb)
        safe_source = _safe_public_url(raw_source)

        # Surface a URL and remember which dict it came from, so the reported
        # width/height describe the URL we actually return rather than a
        # dropped one.
        if safe_image:
            image_url, image_dims = safe_image, properties
        elif not _is_url_present(raw_image):
            image_url, image_dims = safe_thumb, thumbnail
        else:
            image_url, image_dims = "", {}

        if safe_thumb:
            thumbnail_url, thumb_dims = safe_thumb, thumbnail
        elif not _is_url_present(raw_thumb):
            thumbnail_url, thumb_dims = safe_image, properties
        else:
            thumbnail_url, thumb_dims = "", {}

        if not image_url and not thumbnail_url:
            continue

        dims = image_dims if image_url else thumb_dims

        normalized_results.append(
            {
                "title": item.get("title", ""),
                "image_url": image_url,
                "thumbnail_url": thumbnail_url,
                "source_url": safe_source,
                "source": item.get("source", ""),
                "width": dims.get("width"),
                "height": dims.get("height"),
            }
        )
        if len(normalized_results) >= count:
            break

    if not normalized_results:
        return json.dumps({"error": "No safe image URLs found", "query": query}, ensure_ascii=False)

    output = {
        "query": query,
        "total_results": len(normalized_results),
        "results": normalized_results,
        "usage_hint": "Use the 'image_url' values as reference images in image generation. Download them first if needed.",
    }
    return json.dumps(output, indent=2, ensure_ascii=False)

"""Stateful, loop-affine browser sessions backed by Playwright.

Playwright's async objects (``Browser``/``BrowserContext``/``Page``) are affine
to the event loop that created them. DeerFlow tools may be awaited on the
Gateway loop, the TUI loop, or a fresh test loop, and a browser session must
survive across turns of the same thread. To decouple Playwright's loop from the
caller's loop, every Playwright operation runs on one private daemon event loop
(same approach the BoxLite provider uses for its loop-affine box handles); async
tools await the result via :func:`asyncio.wrap_future`.

Playwright itself is an optional dependency — it is imported lazily inside the
private loop so the core harness installs without it.
"""

from __future__ import annotations

import asyncio
import contextlib
import logging
import os
import threading
import time
from collections.abc import Callable, Coroutine
from dataclasses import dataclass, field
from typing import TYPE_CHECKING, Any, Literal, TypeVar
from urllib.parse import urlparse

if TYPE_CHECKING:
    from playwright.async_api import Browser, BrowserContext, Page, Playwright

logger = logging.getLogger(__name__)

T = TypeVar("T")
ScreenshotType = Literal["png", "jpeg", "webp"]

# Element roles/tags treated as interactive when building a page snapshot. The
# model addresses elements by the ``data-df-ref`` index this snapshot stamps, so
# it never has to guess a CSS selector or hold a stale element handle.
_SNAPSHOT_JS = r"""
() => {
  // Clear ref stamps from any previous snapshot first. GitHub-style SPAs keep
  // stale (now-hidden) nodes in the DOM carrying old data-df-ref values; if we
  // don't strip them, a later click selector like [data-df-ref="5"] can match
  // the hidden leftover ahead of the current visible element in DOM order and
  // time out waiting for it to become actionable.
  for (const stale of document.querySelectorAll("[data-df-ref]")) {
    stale.removeAttribute("data-df-ref");
  }
  const INTERACTIVE = new Set(["A", "BUTTON", "INPUT", "TEXTAREA", "SELECT"]);
  const results = [];
  let ref = 0;
  const nodes = document.querySelectorAll(
    "a, button, input, textarea, select, [role=button], [role=link], [role=tab], [role=checkbox], [onclick]"
  );
  for (const el of nodes) {
    const rect = el.getBoundingClientRect();
    const visible = rect.width > 0 && rect.height > 0 &&
      window.getComputedStyle(el).visibility !== "hidden" &&
      window.getComputedStyle(el).display !== "none";
    if (!visible) continue;
    ref += 1;
    el.setAttribute("data-df-ref", String(ref));
    const tag = el.tagName.toLowerCase();
    const role = el.getAttribute("role") || "";
    const type = el.getAttribute("type") || "";
    let name = (el.getAttribute("aria-label") || el.getAttribute("name") ||
      el.getAttribute("placeholder") || el.innerText || el.value || "").trim();
    if (name.length > 120) name = name.slice(0, 120) + "…";
    results.push({ ref, tag, role, type, name });
    if (results.length >= 200) break;
  }
  return { url: location.href, title: document.title, elements: results };
}
"""


_WHEEL_SCROLL_JS = r"""
({ x, y, dx, dy }) => {
  const root = document.scrollingElement || document.documentElement;
  const candidates = [];
  let node = document.elementFromPoint(x, y);

  while (node && node !== document.documentElement) {
    if (node instanceof Element) {
      candidates.push(node);
    }
    node = node.parentElement;
  }
  candidates.push(root);

  const canScroll = (el, axis, delta) => {
    if (!delta || !el) {
      return false;
    }
    const max =
      axis === "y"
        ? el.scrollHeight - el.clientHeight
        : el.scrollWidth - el.clientWidth;
    if (max <= 0) {
      return false;
    }
    const current = axis === "y" ? el.scrollTop : el.scrollLeft;
    return delta < 0 ? current > 0 : current < max;
  };

  for (const el of candidates) {
    if (!canScroll(el, "y", dy) && !canScroll(el, "x", dx)) {
      continue;
    }
    const beforeLeft = el.scrollLeft;
    const beforeTop = el.scrollTop;
    el.scrollBy({ left: dx, top: dy, behavior: "auto" });
    return el.scrollLeft !== beforeLeft || el.scrollTop !== beforeTop;
  }

  const beforeX = window.scrollX;
  const beforeY = window.scrollY;
  window.scrollBy({ left: dx, top: dy, behavior: "auto" });
  return window.scrollX !== beforeX || window.scrollY !== beforeY;
}
"""


# Per-action timeout for clicks. Kept well under the session default (30s) so a
# stale/invalid ref fails fast and the model can re-snapshot instead of blocking
# the whole browsing loop (and tripping the agent loop-detection safety stop).
_CLICK_TIMEOUT_MS = 8000
# Short, best-effort settle wait after a click. SPA (client-side) navigations
# never fire a fresh load event, so this must never block the action.
_POST_CLICK_LOAD_TIMEOUT_MS = 3000
_LIVE_FRAME_JPEG_QUALITY = 85
_MANUAL_LIVE_FRAME_MIN_INTERVAL_S = 0.75
_LIVE_FRAME_INPUT_INTERVAL_S = 0.05
_LIVE_FRAME_SETTLE_DELAYS_S = (0.8, 2.0)

# Bound per-thread Chromium accumulation on a long-running multi-user gateway.
# Sessions unused past the idle timeout are lazily evicted on the next
# get_session call, and the LRU session is closed once the cap is exceeded.
_DEFAULT_MAX_SESSIONS = 32
_DEFAULT_IDLE_TIMEOUT_S = 30 * 60.0


def browser_multi_worker_error(workers: int | None = None) -> str | None:
    """Return the fail-closed reason for process-local browser sessions."""
    if workers is None:
        try:
            workers = int(os.environ.get("GATEWAY_WORKERS", "1"))
        except (TypeError, ValueError):
            workers = 1
    if workers <= 1:
        return None
    return f"GATEWAY_WORKERS={workers} cannot enable agentic browser tools: browser sessions are process-local and uvicorn does not provide thread affinity. Set GATEWAY_WORKERS=1 or disable the browser_navigate tool."


def ensure_browser_worker_compatibility() -> None:
    """Reject runtime browser use when requests can land in another worker."""
    error = browser_multi_worker_error()
    if error is not None:
        raise RuntimeError(error)


class BrowserSessionCapacityError(RuntimeError):
    """Raised when the browser session cap has no evictable slot."""


class BrowserLiveViewerError(RuntimeError):
    """Raised when a second Live viewer tries to attach to a session."""


def _is_playwright_timeout_error(exc: Exception) -> bool:
    """Recognize Playwright timeouts without requiring Playwright at import time."""
    return exc.__class__.__name__ == "TimeoutError" and exc.__class__.__module__.startswith("playwright.")


def redact_browser_url(url: str) -> str:
    """Drop query/fragment so a blocked-URL log line can't leak tokens/PII."""
    try:
        parsed = urlparse(url)
        return f"{parsed.scheme}://{parsed.netloc}{parsed.path}"
    except Exception:
        return "<unparsable-url>"


class _PlaywrightLoopThread:
    """A private asyncio event loop running on a dedicated daemon thread."""

    def __init__(self) -> None:
        self._loop = asyncio.new_event_loop()
        self._thread = threading.Thread(target=self._run, name="deerflow-browser-loop", daemon=True)
        self._thread.start()

    def _run(self) -> None:
        asyncio.set_event_loop(self._loop)
        self._loop.run_forever()

    async def run(self, coro: Coroutine[Any, Any, T]) -> T:
        """Schedule *coro* on the private loop and await it from any loop."""
        future = asyncio.run_coroutine_threadsafe(coro, self._loop)
        return await asyncio.wrap_future(future)

    def submit(self, coro: Coroutine[Any, Any, Any]) -> None:
        """Schedule *coro* on the private loop without blocking the caller."""
        future = asyncio.run_coroutine_threadsafe(coro, self._loop)

        def _log_failure(done: Any) -> None:
            try:
                done.result()
            except Exception as exc:
                logger.debug("browser background task failed: %s", exc)

        future.add_done_callback(_log_failure)

    def run_sync(self, coro: Coroutine[Any, Any, T], timeout: float | None = None) -> T:
        future = asyncio.run_coroutine_threadsafe(coro, self._loop)
        return future.result(timeout=timeout)


@dataclass
class SnapshotElement:
    ref: int
    tag: str
    role: str
    type: str
    name: str

    def render(self) -> str:
        label = self.role or self.tag
        detail = f" type={self.type}" if self.type else ""
        name = self.name or "(no text)"
        return f"[{self.ref}] {label}{detail}: {name}"


@dataclass
class PageSnapshot:
    url: str
    title: str
    elements: list[SnapshotElement] = field(default_factory=list)

    def render(self) -> str:
        lines = [f"URL: {self.url}", f"Title: {self.title}", ""]
        if not self.elements:
            lines.append("No interactive elements detected.")
        else:
            lines.append("Interactive elements (address them by [ref] number):")
            lines.extend(el.render() for el in self.elements)
        return "\n".join(lines)


@dataclass
class BrowserTab:
    index: int
    url: str
    title: str
    active: bool


class BrowserSession:
    """A single Playwright browser+page bound to the private loop."""

    def __init__(
        self,
        loop: _PlaywrightLoopThread,
        *,
        headless: bool,
        timeout_ms: int,
        viewport: dict[str, int],
        cdp_url: str | None = None,
        url_guard: Callable[[str], str | None] | None = None,
        on_activity: Callable[[], None] | None = None,
    ) -> None:
        self._loop = loop
        self._headless = headless
        self._timeout_ms = timeout_ms
        self._viewport = viewport
        # Optional SSRF guard applied at the browser request boundary. It returns
        # an error string to block a URL (redirect/popup/subresource) or None to
        # allow it. The explicit navigate URL is screened by the caller, but
        # Playwright follows redirects and issues subresource/popup requests that
        # bypass that single check — so we also validate every request the page
        # makes here, catching a public URL that 30x-redirects to a private or
        # cloud-metadata host.
        self._url_guard = url_guard
        self._request_guard_bound = False
        # When set, attach to an already-running Chrome via the DevTools
        # Protocol (like Codex's "connect to your real browser") instead of
        # launching a private headless instance. The user watches the agent
        # drive their own visible browser, with their real login sessions.
        self._cdp_url = cdp_url
        self._on_activity = on_activity
        self._activity_lock = threading.Lock()
        self._active_refs = 0
        self._connected_over_cdp = False
        self._playwright: Playwright | None = None
        self._browser: Browser | None = None
        self._context: BrowserContext | None = None
        self._page: Page | None = None
        # Tool calls and the Live WebSocket share this session and can observe a
        # closed page concurrently. Only one caller may rebuild the browser
        # hierarchy; the second check inside the lock reuses its result.
        self._ensure_page_lock = asyncio.Lock()
        # Live screencast state. When streaming, ``_on_frame`` is retained so the
        # screencast can be re-bound to a new page — login/OAuth flows commonly
        # open a popup or a fresh tab, and the user must see (and drive) it.
        self._on_frame: Callable[[bytes], None] | None = None
        # The page the live screencast's CDP session is currently bound to. Frames
        # are captured from ``self._page`` (the live active page), but the CDP
        # repaint signal is tied to a specific page; when the active page diverges
        # from this one we must rebind so new-page repaints keep driving frames.
        self._screencast_page: Page | None = None
        # Guards against re-entrant rebinds: while (re)binding the screencast we
        # may call _ensure_page (which routes through _set_active_page); without
        # this flag that would schedule another rebind and recurse.
        self._screencast_binding = False
        self._last_manual_live_frame_at = 0.0
        self._settle_live_frames_pending = False
        self._input_live_frame_generation = 0
        self._input_live_frame_pending = False
        self._page_listener_bound = False

    @property
    def active_refs(self) -> int:
        with self._activity_lock:
            return self._active_refs

    def _pin(self) -> None:
        """Keep this session in the manager while a caller owns it."""
        with self._activity_lock:
            self._active_refs += 1

    def _unpin(self) -> None:
        with self._activity_lock:
            self._active_refs = max(0, self._active_refs - 1)

    @contextlib.contextmanager
    def _activity(self):
        """Reference a real browser operation and refresh its recency."""
        self._pin()
        if self._on_activity is not None:
            self._on_activity()
        try:
            yield
        finally:
            self._unpin()

    async def _ensure_page(self) -> Page:
        if self._page is not None and not self._page.is_closed():
            return self._page
        async with self._ensure_page_lock:
            if self._page is not None and not self._page.is_closed():
                return self._page
            from playwright.async_api import async_playwright

            if self._playwright is None:
                self._playwright = await async_playwright().start()

            if self._cdp_url:
                # Attach to the user's running Chrome (started with
                # --remote-debugging-port). Reuse its default context + an existing
                # tab: calling new_context()/new_page() on a CDP-attached real
                # Chrome trips "Browser context management is not supported", so we
                # adopt the tab Chrome already opened instead.
                if self._browser is None or not self._browser.is_connected():
                    self._browser = await self._playwright.chromium.connect_over_cdp(self._cdp_url)
                    self._connected_over_cdp = True
                    # CDP-attached real Chrome owns its own browsing context, so the
                    # SSRF request guard is intentionally NOT installed for it (see
                    # _install_request_guard). Surface that to operators — for this
                    # session redirects/subresources to private/metadata hosts are
                    # not aborted; cdp_url is documented local/trusted-only.
                    logger.warning(
                        "browser SSRF request guard is disabled for CDP-attached session (cdp_url=%s)",
                        redact_browser_url(self._cdp_url),
                    )
                self._context = self._browser.contexts[0] if self._browser.contexts else await self._browser.new_context()
                self._context.set_default_timeout(self._timeout_ms)
                existing = self._context.pages
                self._set_active_page(existing[-1] if existing else await self._context.new_page())
                self._bind_new_page_listener()
                return self._page

            if self._browser is None or not self._browser.is_connected():
                self._browser = await self._playwright.chromium.launch(headless=self._headless)
            # device_scale_factor=2 renders screenshots at retina density so the
            # panel stays crisp when the image is scaled up to fill the view.
            self._context = await self._browser.new_context(viewport=self._viewport, device_scale_factor=2)
            self._context.set_default_timeout(self._timeout_ms)
            await self._install_request_guard()
            self._set_active_page(await self._context.new_page())
            self._bind_new_page_listener()
            return self._page

    def _set_active_page(self, page: Page) -> None:
        """Adopt *page* as the active page and keep the live screencast on it.

        Every path that changes the active page (initial/rebuilt page, popups and
        new tabs, explicit tab switches) routes through here so the live stream can
        never drift onto a stale page. The CDP screencast's repaint signal is bound
        to one page; when the active page diverges from the one the screencast is
        bound to, rebind it. Rebinding is scheduled with error handling so a
        transient failure cannot leave the callback un-awaited and silently
        swallowed (the previous fire-and-forget rebind could strand Live on the
        old page — address bar / snapshot moved on, frames did not).
        """
        self._page = page
        if self._on_frame is not None and not self._screencast_binding and page is not self._screencast_page:
            asyncio.ensure_future(self._rebind_screencast_safe())

    def _bind_new_page_listener(self) -> None:
        """Follow popups/new tabs so auth flows stay visible and controllable.

        Login and OAuth consent screens routinely open a popup or a fresh tab.
        Without following it the user sees a frozen frame and cannot authorize.
        On a new page we adopt it as the active page and, if a screencast is
        running, re-bind it so the stream tracks the tab the user must act on.
        """
        if self._context is None or self._page_listener_bound:
            return

        def _on_new_page(page: Page) -> None:
            self._set_active_page(page)

        self._context.on("page", _on_new_page)
        self._page_listener_bound = True

    async def _install_request_guard(self) -> None:
        """Abort any request whose URL fails the SSRF guard.

        Runs at the context level so it covers the top navigation, every
        redirect hop, popups/new tabs, iframes, and subresource fetches — the
        paths a one-time initial-URL check cannot see. A public URL that
        redirects to ``http://169.254.169.254/...`` is aborted before the
        response is exposed through snapshots/text. Skipped for CDP-attached
        real Chrome, which owns its own browsing context.
        """
        if self._url_guard is None or self._context is None or self._request_guard_bound or self._cdp_url:
            return

        guard = self._url_guard

        async def _route(route: Any) -> None:
            url = ""
            with contextlib.suppress(Exception):
                url = route.request.url
            if url.startswith(("http://", "https://")) and guard(url) is not None:
                logger.warning("browser request blocked by SSRF guard: %s", redact_browser_url(url))
                with contextlib.suppress(Exception):
                    await route.abort("blockedbyclient")
                return
            with contextlib.suppress(Exception):
                await route.continue_()

        with contextlib.suppress(Exception):
            await self._context.route("**/*", _route)
            self._request_guard_bound = True

    async def _rebind_screencast(self) -> None:
        if self._on_frame is not None:
            await self._start_screencast(self._on_frame)

    async def _rebind_screencast_safe(self) -> None:
        try:
            await self._rebind_screencast()
        except Exception as exc:
            logger.debug("browser live screencast rebind failed: %s", exc)

    async def _navigate(self, url: str) -> PageSnapshot:
        page = await self._ensure_page()
        await page.goto(url, wait_until="domcontentloaded")
        return await self._snapshot_impl(page)

    async def _snapshot_impl(self, page: Page) -> PageSnapshot:
        data = await page.evaluate(_SNAPSHOT_JS)
        elements = [SnapshotElement(ref=int(e["ref"]), tag=e["tag"], role=e["role"], type=e["type"], name=e["name"]) for e in data["elements"]]
        return PageSnapshot(url=data["url"], title=data["title"], elements=elements)

    async def _snapshot(self) -> PageSnapshot:
        page = await self._ensure_page()
        return await self._snapshot_impl(page)

    async def _click(self, ref: int) -> PageSnapshot:
        page = await self._ensure_page()
        selector = f'[data-df-ref="{ref}"]'
        base = page.locator(selector)

        # Fast-fail on a stale ref instead of blocking on the 30s session
        # default: after a SPA re-render the ref may no longer exist, and the
        # model should re-snapshot and retry rather than the browsing loop
        # stalling until it trips the agent loop-detection safety stop.
        if await base.count() == 0:
            raise RuntimeError(f"element [{ref}] is no longer on the page; call browser_snapshot to get fresh refs")

        locator = base.first
        # Bring the target into view; harmless if it is already on-screen.
        try:
            await locator.scroll_into_view_if_needed(timeout=_CLICK_TIMEOUT_MS)
        except Exception as exc:
            if not _is_playwright_timeout_error(exc):
                raise

        try:
            await locator.click(timeout=_CLICK_TIMEOUT_MS)
        except Exception as exc:
            if not _is_playwright_timeout_error(exc):
                raise
            raise RuntimeError(f"element [{ref}] was not clickable within {_CLICK_TIMEOUT_MS // 1000}s; the page may have changed — call browser_snapshot and retry") from exc

        # SPA (client-side) navigations never fire a fresh load event, so this
        # settle wait is best-effort and must never block the snapshot.
        try:
            await page.wait_for_load_state("domcontentloaded", timeout=_POST_CLICK_LOAD_TIMEOUT_MS)
        except Exception as exc:
            if not _is_playwright_timeout_error(exc):
                raise

        return await self._snapshot_impl(page)

    async def _type(self, ref: int, text: str, submit: bool) -> PageSnapshot:
        page = await self._ensure_page()
        selector = f'[data-df-ref="{ref}"]'
        await page.fill(selector, text)
        if submit:
            await page.press(selector, "Enter")
            # Best-effort settle; a client-side search/submit may never fire a
            # fresh load event, so this must not block the snapshot for 30s.
            try:
                await page.wait_for_load_state("domcontentloaded", timeout=_POST_CLICK_LOAD_TIMEOUT_MS)
            except Exception as exc:
                if not _is_playwright_timeout_error(exc):
                    raise
        return await self._snapshot_impl(page)

    async def _get_text(self, max_chars: int) -> str:
        page = await self._ensure_page()
        text = await page.inner_text("body")
        return text[:max_chars]

    async def _screenshot_bytes(
        self,
        full_page: bool,
        image_type: ScreenshotType,
        quality: int | None,
    ) -> bytes:
        page = await self._ensure_page()
        if quality is None:
            return await page.screenshot(full_page=full_page, type=image_type)
        return await page.screenshot(full_page=full_page, type=image_type, quality=quality)

    async def _live_frame(self) -> bytes:
        page = await self._ensure_page()
        return await page.screenshot(type="jpeg", quality=_LIVE_FRAME_JPEG_QUALITY)

    async def _emit_live_frame(self) -> None:
        if self._on_frame is None:
            return
        with self._activity():
            self._on_frame(await self._live_frame())
            self._last_manual_live_frame_at = time.monotonic()

    async def _settle_live_frames(self) -> None:
        previous_delay = 0.0
        try:
            for delay in _LIVE_FRAME_SETTLE_DELAYS_S:
                await asyncio.sleep(max(0.0, delay - previous_delay))
                previous_delay = delay
                await self._emit_live_frame()
        finally:
            self._settle_live_frames_pending = False

    def _schedule_settle_live_frames(self) -> None:
        if self._settle_live_frames_pending:
            return
        self._settle_live_frames_pending = True
        asyncio.ensure_future(self._settle_live_frames())

    async def _push_live_frame(self) -> None:
        if self._on_frame is None:
            return
        elapsed = time.monotonic() - self._last_manual_live_frame_at
        if elapsed >= _MANUAL_LIVE_FRAME_MIN_INTERVAL_S:
            await self._emit_live_frame()
        # One frame is often too early for SPAs: the URL may have changed while
        # the page body is still rendering. Add a small, bounded settle burst
        # instead of returning to continuous screencast.
        self._schedule_settle_live_frames()

    async def _flush_input_live_frames(self) -> None:
        try:
            # Coalesce the first burst, then keep refreshing at a bounded cadence
            # while input continues. A trailing debounce would freeze the visible
            # page until a wheel/keyboard gesture stopped.
            await asyncio.sleep(_LIVE_FRAME_INPUT_INTERVAL_S)
            while self._on_frame is not None:
                generation = self._input_live_frame_generation
                await self._emit_live_frame()
                if generation == self._input_live_frame_generation:
                    self._schedule_settle_live_frames()
                    return
                await asyncio.sleep(_LIVE_FRAME_INPUT_INTERVAL_S)
        finally:
            self._input_live_frame_pending = False

    def _schedule_input_live_frame(self) -> None:
        self._input_live_frame_generation += 1
        if self._input_live_frame_pending:
            return
        self._input_live_frame_pending = True
        asyncio.ensure_future(self._flush_input_live_frames())

    async def _back(self) -> PageSnapshot:
        page = await self._ensure_page()
        await page.go_back(wait_until="domcontentloaded")
        return await self._snapshot_impl(page)

    async def _current_url(self) -> str | None:
        page = await self._ensure_page()
        try:
            return page.url
        except Exception:
            return None

    async def _tabs(self) -> list[BrowserTab]:
        await self._ensure_page()
        if self._context is None:
            return []
        pages = [page for page in self._context.pages if not page.is_closed()]
        tabs: list[BrowserTab] = []
        for index, page in enumerate(pages):
            try:
                title = await page.title()
            except Exception:
                title = ""
            try:
                url = page.url
            except Exception:
                url = ""
            tabs.append(BrowserTab(index=index, url=url, title=title, active=page == self._page))
        return tabs

    async def _activate_tab(self, index: int) -> None:
        await self._ensure_page()
        if self._context is None:
            return
        pages = [page for page in self._context.pages if not page.is_closed()]
        if index < 0 or index >= len(pages):
            return
        target = pages[index]
        await target.bring_to_front()
        # This path is async, so rebind the screencast inline (awaited) rather
        # than going through _set_active_page's scheduled rebind — that keeps the
        # frame source aligned with the switched-to tab before this call returns.
        self._page = target
        if self._on_frame is not None and target is not self._screencast_page:
            await self._rebind_screencast()

    async def _close(self) -> None:
        try:
            with contextlib.suppress(Exception):
                await self._stop_screencast()
            if self._connected_over_cdp:
                # Attached to the user's real Chrome — never close their browser,
                # context, or the tab we adopted. Just disconnect Playwright.
                if self._browser is not None:
                    with contextlib.suppress(Exception):
                        await self._browser.close()
            else:
                if self._context is not None:
                    with contextlib.suppress(Exception):
                        await self._context.close()
                if self._browser is not None:
                    with contextlib.suppress(Exception):
                        await self._browser.close()
            if self._playwright is not None:
                with contextlib.suppress(Exception):
                    await self._playwright.stop()
        finally:
            self._playwright = None
            self._browser = None
            self._context = None
            self._page = None
            self._screencast_page = None
            self._connected_over_cdp = False
            self._on_frame = None
            self._settle_live_frames_pending = False
            self._input_live_frame_generation += 1
            self._page_listener_bound = False
            self._request_guard_bound = False

    async def _start_screencast(self, on_frame: Callable[[bytes], None]) -> None:
        """Start Live mode and send an initial JPEG frame.

        This used to attach Chrome's CDP screencast and then turn every repaint
        into a high-quality Playwright screenshot. That made GitHub-like pages
        expensive to open because a mostly static panel still kept the headless
        renderer/GPU busy. Live control now uses on-demand frames instead:
        initial connect, browser tool completion, and user input all push a
        throttled screenshot.
        """
        page = await self._ensure_page()
        if self._on_frame is not None and self._on_frame is not on_frame:
            raise BrowserLiveViewerError("Browser live stream already has an active viewer")
        await self._stop_screencast()
        self._on_frame = on_frame
        self._screencast_page = page
        await self._emit_live_frame()
        self._schedule_settle_live_frames()

    async def _stop_screencast(self, on_frame: Callable[[bytes], None] | None = None) -> None:
        if on_frame is not None and self._on_frame is not on_frame:
            return
        self._on_frame = None
        self._settle_live_frames_pending = False
        self._input_live_frame_generation += 1
        self._screencast_page = None

    async def _dispatch_input(self, event: dict) -> None:
        page = await self._ensure_page()
        vw = self._viewport.get("width", 1280)
        vh = self._viewport.get("height", 720)
        etype = event.get("type")
        if etype in {"click", "move", "down", "up"}:
            x = float(event.get("nx", 0)) * vw
            y = float(event.get("ny", 0)) * vh
            if etype == "click":
                await page.mouse.click(x, y)
            elif etype == "move":
                await page.mouse.move(x, y)
            elif etype == "down":
                await page.mouse.move(x, y)
                await page.mouse.down()
            elif etype == "up":
                await page.mouse.up()
        elif etype == "wheel":
            dx = float(event.get("dx", 0))
            dy = float(event.get("dy", 0))
            nx = event.get("nx")
            ny = event.get("ny")
            x = vw / 2
            y = vh / 2
            if nx is not None and ny is not None:
                try:
                    x = max(0.0, min(1.0, float(nx))) * vw
                    y = max(0.0, min(1.0, float(ny))) * vh
                    await page.mouse.move(x, y)
                except (TypeError, ValueError) as e:
                    logger.debug("invalid browser wheel coordinates: %s", e)
            try:
                handled = bool(await page.evaluate(_WHEEL_SCROLL_JS, {"x": x, "y": y, "dx": dx, "dy": dy}))
            except Exception as e:
                logger.debug("browser js scroll failed: %s", e)
                handled = False
            if not handled:
                await page.mouse.wheel(dx, dy)
        elif etype == "key":
            key = event.get("key")
            if key:
                await page.keyboard.press(key)
        elif etype == "text":
            text = event.get("text")
            if text:
                await page.keyboard.type(text)
        elif etype == "navigate":
            url = event.get("url")
            if url:
                await page.goto(url, wait_until="domcontentloaded")
        elif etype == "back":
            await page.go_back(wait_until="domcontentloaded")
        elif etype == "forward":
            await page.go_forward(wait_until="domcontentloaded")
        elif etype == "activate_tab":
            index = event.get("index")
            if isinstance(index, int) and not isinstance(index, bool):
                await self._activate_tab(index)
        if etype != "move":
            self._schedule_input_live_frame()

    # Public API — each marshals onto the private loop.
    async def navigate(self, url: str) -> PageSnapshot:
        with self._activity():
            return await self._loop.run(self._navigate(url))

    async def snapshot(self) -> PageSnapshot:
        with self._activity():
            return await self._loop.run(self._snapshot())

    async def click(self, ref: int) -> PageSnapshot:
        with self._activity():
            return await self._loop.run(self._click(ref))

    async def type_text(self, ref: int, text: str, submit: bool = False) -> PageSnapshot:
        with self._activity():
            return await self._loop.run(self._type(ref, text, submit))

    async def get_text(self, max_chars: int = 8000) -> str:
        with self._activity():
            return await self._loop.run(self._get_text(max_chars))

    async def screenshot_bytes(
        self,
        full_page: bool = False,
        *,
        image_type: ScreenshotType = "png",
        quality: int | None = None,
    ) -> bytes:
        with self._activity():
            return await self._loop.run(self._screenshot_bytes(full_page, image_type, quality))

    async def live_frame(self) -> bytes:
        with self._activity():
            return await self._loop.run(self._live_frame())

    async def push_live_frame(self) -> None:
        with self._activity():
            await self._loop.run(self._push_live_frame())

    def schedule_live_frames(self) -> None:
        self._loop.submit(self._push_live_frame())

    async def back(self) -> PageSnapshot:
        with self._activity():
            return await self._loop.run(self._back())

    async def current_url(self) -> str | None:
        with self._activity():
            return await self._loop.run(self._current_url())

    async def tabs(self) -> list[BrowserTab]:
        with self._activity():
            return await self._loop.run(self._tabs())

    async def start_screencast(self, on_frame: Callable[[bytes], None]) -> None:
        with self._activity():
            await self._loop.run(self._start_screencast(on_frame))

    async def stop_screencast(self, on_frame: Callable[[bytes], None] | None = None) -> None:
        with self._activity():
            await self._loop.run(self._stop_screencast(on_frame))

    async def dispatch_input(self, event: dict) -> None:
        with self._activity():
            await self._loop.run(self._dispatch_input(event))

    async def close(self) -> None:
        await self._loop.run(self._close())


class BrowserSessionManager:
    """Process-local registry of per-thread browser sessions.

    Sessions are keyed by ``thread_id`` and each owns a headless Chromium
    process, so a long-running multi-user gateway would otherwise accumulate one
    browser per thread that ever used the tools (a real memory/FD leak). To bound
    that, ``get_session`` lazily evicts sessions that have been idle past
    ``idle_timeout_s`` and enforces a ``max_sessions`` cap by closing the
    least-recently-used unpinned session. Active browser operations and Live
    WebSocket leases are reference-counted, so eviction never closes a session
    while it is in use. Admission is a hard bound: when every existing session
    is pinned, a new thread is rejected instead of exceeding ``max_sessions``.
    Eviction is fire-and-forget on the private Playwright loop so it never
    blocks the caller; the just-requested thread is always kept.
    """

    def __init__(self, *, max_sessions: int = _DEFAULT_MAX_SESSIONS, idle_timeout_s: float = _DEFAULT_IDLE_TIMEOUT_S) -> None:
        self._loop: _PlaywrightLoopThread | None = None
        self._sessions: dict[str, BrowserSession] = {}
        self._last_used: dict[str, float] = {}
        self._max_sessions = max_sessions
        self._idle_timeout_s = idle_timeout_s
        self._lock = threading.Lock()

    def _touch_session(self, key: str) -> None:
        with self._lock:
            if key in self._sessions:
                self._last_used[key] = time.monotonic()

    def _ensure_loop(self) -> _PlaywrightLoopThread:
        if self._loop is None:
            self._loop = _PlaywrightLoopThread()
        return self._loop

    def get_session(
        self,
        thread_id: str | None,
        *,
        headless: bool = True,
        timeout_ms: int = 30000,
        viewport: dict[str, int] | None = None,
        cdp_url: str | None = None,
        allow_unguarded_cdp: bool = False,
        url_guard: Callable[[str], str | None] | None = None,
        pin: bool = False,
    ) -> BrowserSession:
        ensure_browser_worker_compatibility()
        if cdp_url and not allow_unguarded_cdp:
            raise RuntimeError("cdp_url uses a browser context where DeerFlow cannot enforce its SSRF request guard; set allow_unguarded_cdp: true only for an explicitly trusted local Chrome session")
        key = thread_id or "default"
        now = time.monotonic()
        evicted: list[BrowserSession] = []
        with self._lock:
            session = self._sessions.get(key)
            if session is None:
                evicted.extend(self._collect_idle_locked(keep_key=key, now=now))
                if self._max_sessions > 0 and len(self._sessions) >= self._max_sessions:
                    lru = self._pop_lru_unpinned_locked(excluded_keys={key})
                    if lru is None:
                        raise BrowserSessionCapacityError(f"Browser session capacity is full ({self._max_sessions}); close an active Live browser before opening another")
                    evicted.append(lru)
                session = BrowserSession(
                    self._ensure_loop(),
                    headless=headless,
                    timeout_ms=timeout_ms,
                    viewport=viewport or {"width": 1280, "height": 720},
                    cdp_url=cdp_url,
                    url_guard=url_guard,
                    on_activity=lambda: self._touch_session(key),
                )
                self._sessions[key] = session
            if pin:
                session._pin()
            self._last_used[key] = now
            evicted.extend(self._collect_evictable_locked(keep_key=key, now=now))
        for evicted_session in evicted:
            self._schedule_close(evicted_session)
        return session

    @contextlib.contextmanager
    def acquire_session(self, thread_id: str | None, **kwargs: Any):
        """Acquire an atomically pinned session for one browser operation."""
        key = thread_id or "default"
        session = self.get_session(key, pin=True, **kwargs)
        try:
            yield session
        finally:
            self.release_session(key, session)

    def release_session(self, thread_id: str | None, session: BrowserSession) -> None:
        """Release a lease and restore idle/LRU bounds when it becomes evictable."""
        key = thread_id or "default"
        session._unpin()
        now = time.monotonic()
        with self._lock:
            evicted = self._collect_evictable_locked(keep_key=None, now=now) if self._sessions.get(key) is session else []
        for evicted_session in evicted:
            self._schedule_close(evicted_session)

    def _collect_evictable_locked(self, *, keep_key: str | None, now: float) -> list[BrowserSession]:
        """Drop idle/over-cap sessions from the registry; return them for close.

        Must be called under ``self._lock``. When set, ``keep_key`` (the
        just-touched thread) is never evicted so a new request cannot lose its
        session. Lease release passes ``None`` so newly unpinned sessions can
        restore the configured bounds without waiting for another request.
        """
        to_close: list[BrowserSession] = []
        to_close.extend(self._collect_idle_locked(keep_key=keep_key, now=now))
        if self._max_sessions > 0:
            excluded = {keep_key} if keep_key is not None else set()
            while len(self._sessions) > self._max_sessions:
                session = self._pop_lru_unpinned_locked(excluded_keys=excluded)
                if session is None:
                    break
                to_close.append(session)
        return to_close

    def _collect_idle_locked(self, *, keep_key: str | None, now: float) -> list[BrowserSession]:
        """Drop idle, unpinned sessions from the registry."""
        to_close: list[BrowserSession] = []
        if self._idle_timeout_s > 0:
            for other_key, last_used in list(self._last_used.items()):
                if other_key == keep_key:
                    continue
                session = self._sessions.get(other_key)
                if session is not None and session.active_refs:
                    continue
                if now - last_used >= self._idle_timeout_s:
                    session = self._sessions.pop(other_key, None)
                    self._last_used.pop(other_key, None)
                    if session is not None:
                        to_close.append(session)
        return to_close

    def _pop_lru_unpinned_locked(self, *, excluded_keys: set[str]) -> BrowserSession | None:
        candidates = [(last_used, other_key) for other_key, last_used in self._last_used.items() if other_key not in excluded_keys and (session := self._sessions.get(other_key)) is not None and not session.active_refs]
        if not candidates:
            return None
        _, lru_key = min(candidates)
        session = self._sessions.pop(lru_key, None)
        self._last_used.pop(lru_key, None)
        return session

    def _schedule_close(self, session: BrowserSession) -> None:
        loop = self._loop
        if loop is None:
            return
        with contextlib.suppress(Exception):
            loop.submit(session._close())

    async def close_session(self, thread_id: str | None) -> bool:
        key = thread_id or "default"
        with self._lock:
            session = self._sessions.pop(key, None)
            self._last_used.pop(key, None)
        if session is None:
            return False
        await session.close()
        return True

    async def close_all_sessions(self) -> int:
        with self._lock:
            sessions = list(self._sessions.values())
            self._sessions.clear()
            self._last_used.clear()
        for session in sessions:
            await session.close()
        return len(sessions)


_manager: BrowserSessionManager | None = None
_manager_lock = threading.Lock()


def get_browser_session_manager() -> BrowserSessionManager:
    global _manager
    if _manager is None:
        with _manager_lock:
            if _manager is None:
                _manager = BrowserSessionManager()
    return _manager


def reset_browser_session_manager() -> None:
    """Test hook: drop the process-local manager without closing sessions."""
    global _manager
    with _manager_lock:
        _manager = None

import logging

from langchain.tools import tool

from deerflow.community.url_safety import validate_public_http_url
from deerflow.config import get_app_config

from .crawl4ai_client import Crawl4AiClient

logger = logging.getLogger(__name__)

DEFAULT_BASE_URL = "http://localhost:11235"
DEFAULT_TIMEOUT_S = 30
DEFAULT_FILTER = "fit"
VALID_FILTERS = ("fit", "raw", "bm25", "llm")


def _get_tool_config(tool_name: str) -> dict | None:
    """Return the tool's config extras (model_extra) dict, or None if unconfigured."""
    config = get_app_config().get_tool_config(tool_name)
    if config is None:
        return None
    extras = config.model_extra
    return extras if extras is not None else {}


def _coerce_timeout(value: object, default: int) -> float:
    """Coerce a config timeout into seconds, falling back to ``default`` on bad input.

    Mirrors ``jina_ai._coerce_timeout``: booleans and non-numeric strings fall
    back to the default so e.g. ``timeout: off`` (YAML ``False``) does not become
    ``0.0`` and time out every request against a healthy server.
    """
    if isinstance(value, bool):
        return float(default)
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        try:
            return float(value)
        except ValueError:
            logger.warning("Crawl4AI web_fetch: invalid timeout %r in config; using %ss", value, default)
    return float(default)


def _coerce_bool(value: object, default: bool) -> bool:
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        normalized = value.strip().lower()
        if normalized in {"1", "true", "yes", "on"}:
            return True
        if normalized in {"0", "false", "no", "off"}:
            return False
    return default


def _coerce_filter(value: object) -> str:
    """Normalize and validate the markdown filter, falling back to the default.

    Catches typos / stale values (e.g. ``FIt``, ``fit_content``) at config-read
    time instead of letting them reach the server as an opaque HTTP 400.
    """
    if isinstance(value, str):
        normalized = value.strip().lower()
        if normalized in VALID_FILTERS:
            return normalized
        logger.warning("Crawl4AI web_fetch: unknown filter %r in config; using %r (valid: %s)", value, DEFAULT_FILTER, ", ".join(VALID_FILTERS))
    return DEFAULT_FILTER


def _build_client(cfg: dict | None) -> Crawl4AiClient:
    """Build a ``Crawl4AiClient`` from an already-read ``web_fetch`` config dict.

    Takes the config as an argument (rather than reading it again) so a single
    invocation reads ``get_app_config()`` exactly once and cannot split across a
    concurrent hot-reload.
    """
    base_url = DEFAULT_BASE_URL
    token = ""
    timeout_s: float = float(DEFAULT_TIMEOUT_S)
    if cfg is not None:
        base_url = cfg.get("base_url", base_url)
        token = cfg.get("token", token)
        timeout_s = _coerce_timeout(cfg.get("timeout"), DEFAULT_TIMEOUT_S)
    return Crawl4AiClient(base_url=base_url, token=token, timeout_s=timeout_s)


@tool("web_fetch", parse_docstring=True)
async def web_fetch_tool(url: str) -> str:
    """Fetch the contents of a web page at a given URL.
    Only fetch EXACT URLs that have been provided directly by the user or have been returned in results from the web_search and web_fetch tools.
    This tool can NOT access content that requires authentication, such as private Google Docs or pages behind login walls.
    Do NOT add www. to URLs that do NOT have them.
    URLs must include the schema: https://example.com is a valid URL while example.com is an invalid URL.

    Args:
        url: The URL to fetch the contents of.
    """
    try:
        cfg = _get_tool_config("web_fetch")  # read config once; pass the values down
        allow_private_addresses = _coerce_bool(cfg.get("allow_private_addresses") if cfg is not None else None, False)
        url_error = validate_public_http_url(url, allow_private_addresses=allow_private_addresses)
        if url_error:
            return url_error
        filter_mode = _coerce_filter(cfg.get("filter") if cfg is not None else None)
        client = _build_client(cfg)
        markdown = await client.fetch_markdown(url, filter_mode=filter_mode)

        if markdown.startswith("Error:"):
            return markdown

        return markdown[:4096]

    except Exception as e:
        logger.error(f"Error in web_fetch_tool: {e}")
        return f"Error: {str(e)}"

"""GroundRoute community web search + fetch tools.

GroundRoute (https://groundroute.ai) is a meta search layer: one API in front of
six search engines (Serper, Brave, Exa, Tavily, Firecrawl, Perplexity). It routes
each query to the cheapest engine that clears a quality bar and caches repeats, so
high-volume research runs keep working when one engine is down and pay no more than
going to a single engine direct. Pricing is gain-share: the caller keeps about half
of any cache savings.

This module is self-contained (httpx only, no GroundRoute SDK). The /v1/search
request and response mapping mirrors the GroundRoute MCP server and the verified
Langflow component:
  results[] = {url, title, snippet, content, source_engine, published_at}

`web_search` returns a normalized JSON list of {title, url, snippet, source_engine}.
`web_fetch` reads one URL via GroundRoute mode=page and returns its extracted text.
"""

import json
import logging
import os

import httpx
from langchain.tools import tool

from deerflow.config import get_app_config

logger = logging.getLogger(__name__)

_GROUNDROUTE_ENDPOINT = "https://api.groundroute.ai/v1/search"
_DEFAULT_MAX_RESULTS = 5
# GroundRoute clamps max_results to 1-50 server-side; clamp here too to mirror it.
_MAX_RESULTS_CAP = 50
_TIMEOUT_S = 30.0
_FETCH_SNIPPET_LIMIT = 4096
# Warn at most once per tool ("web_search" / "web_fetch") about a missing key.
_api_key_warned: set[str] = set()


def _get_api_key(tool_name: str) -> str | None:
    """Resolve the GroundRoute key from a given tool's config block, then the env var.

    `tool_name` is the config section to read (web_search vs web_fetch) so a flow that
    runs GroundRoute for fetch but a different engine for search still reads the right
    key. Mirrors serper/exa/firecrawl, which all take the tool name.
    """
    config = get_app_config().get_tool_config(tool_name)
    if config is not None:
        api_key = (config.model_extra or {}).get("api_key")
        if isinstance(api_key, str) and api_key.strip():
            return api_key.strip()
    return os.getenv("GROUNDROUTE_API_KEY")


def _coerce_max_results(value: object, *, default: int = _DEFAULT_MAX_RESULTS) -> int:
    try:
        coerced = int(value)
    except (TypeError, ValueError):
        logger.warning("Invalid GroundRoute max_results=%r; using default %s", value, default)
        coerced = default
    return max(1, min(coerced, _MAX_RESULTS_CAP))


def _missing_key_error(tool_name: str, **context: str) -> str:
    if tool_name not in _api_key_warned:
        _api_key_warned.add(tool_name)
        logger.warning(
            "GroundRoute API key is not set for '%s'. Set GROUNDROUTE_API_KEY in your environment or provide api_key in config.yaml. Get a free key at https://groundroute.ai/keys",
            tool_name,
        )
    return json.dumps({"error": "GROUNDROUTE_API_KEY is not configured", **context}, ensure_ascii=False)


def _post_search(api_key: str, body: dict) -> dict:
    with httpx.Client(timeout=_TIMEOUT_S) as client:
        response = client.post(
            _GROUNDROUTE_ENDPOINT,
            json=body,
            headers={"Authorization": f"Bearer {api_key}"},
        )
    response.raise_for_status()
    return response.json()


@tool("web_search", parse_docstring=True)
def web_search_tool(query: str, max_results: int | None = None) -> str:
    """Search the web for information using GroundRoute.

    GroundRoute routes the query across six search engines and returns the result
    set from the engine it selected, with failover if one engine is unavailable.

    Args:
        query: Search keywords describing what you want to find. Be specific for better results.
        max_results: Maximum number of search results to return. If omitted, uses the configured value (default 5). Clamped to 1-50.
    """
    # Honor the caller-supplied max_results; fall back to config only when omitted.
    if max_results is None:
        config = get_app_config().get_tool_config("web_search")
        if config is not None:
            max_results = (config.model_extra or {}).get("max_results")
    count = _DEFAULT_MAX_RESULTS if max_results is None else _coerce_max_results(max_results)

    api_key = _get_api_key("web_search")
    if not api_key:
        return _missing_key_error("web_search", query=query)

    try:
        data = _post_search(api_key, {"query": query, "max_results": count})
    except httpx.HTTPStatusError as e:
        logger.error("GroundRoute API returned HTTP %s: %s", e.response.status_code, e.response.text)
        return json.dumps(
            {"error": f"GroundRoute API error: HTTP {e.response.status_code}", "query": query},
            ensure_ascii=False,
        )
    except Exception as e:
        logger.error("GroundRoute search failed: %s: %s", type(e).__name__, e)
        return json.dumps({"error": str(e), "query": query}, ensure_ascii=False)

    results = data.get("results") or []
    if not results:
        return json.dumps({"error": "No results found", "query": query}, ensure_ascii=False)

    normalized_results = [
        {
            "title": r.get("title", ""),
            "url": r.get("url", ""),
            "snippet": r.get("snippet", ""),
            "source_engine": r.get("source_engine", ""),
        }
        for r in results
    ]
    return json.dumps(normalized_results, indent=2, ensure_ascii=False)


@tool("web_fetch", parse_docstring=True)
def web_fetch_tool(url: str) -> str:
    """Fetch the contents of a web page at a given URL via GroundRoute.
    Only fetch EXACT URLs that have been provided directly by the user or have been returned in results from the web_search and web_fetch tools.
    This tool can NOT access content that requires authentication, such as private Google Docs or pages behind login walls.
    Do NOT add www. to URLs that do NOT have them.
    URLs must include the schema: https://example.com is a valid URL while example.com is an invalid URL.

    Args:
        url: The URL to fetch the contents of.
    """
    api_key = _get_api_key("web_fetch")
    if not api_key:
        return _missing_key_error("web_fetch", url=url)

    try:
        data = _post_search(api_key, {"query": url, "mode": "page", "max_results": 1})
    except httpx.HTTPStatusError as e:
        logger.error("GroundRoute fetch returned HTTP %s: %s", e.response.status_code, e.response.text)
        return f"Error: GroundRoute API error: HTTP {e.response.status_code}"
    except Exception as e:
        logger.error("GroundRoute fetch failed: %s: %s", type(e).__name__, e)
        return f"Error: {e}"

    results = data.get("results") or []
    if not results:
        return "Error: No results found"

    result = results[0]
    content = result.get("content") or result.get("snippet") or ""
    title = result.get("title", "")
    return f"# {title}\n\n{content[:_FETCH_SNIPPET_LIMIT]}"

import logging
import os

import httpx

logger = logging.getLogger(__name__)

_api_key_warned = False


class JinaClient:
    async def crawl(self, url: str, return_format: str = "html", timeout: int = 10, proxy: str | None = None, trust_env: bool = True) -> str:
        global _api_key_warned
        headers = {
            "Content-Type": "application/json",
            "X-Return-Format": return_format,
            "X-Timeout": str(timeout),
        }
        if os.getenv("JINA_API_KEY"):
            headers["Authorization"] = f"Bearer {os.getenv('JINA_API_KEY')}"
        elif not _api_key_warned:
            _api_key_warned = True
            logger.warning("Jina API key is not set. Provide your own key to access a higher rate limit. See https://jina.ai/reader for more information.")
        data = {"url": url}
        try:
            client_kwargs: dict[str, object] = {"trust_env": trust_env}
            if proxy:
                client_kwargs["proxy"] = proxy
            async with httpx.AsyncClient(**client_kwargs) as client:
                response = await client.post("https://r.jina.ai/", headers=headers, json=data, timeout=timeout)

            if response.status_code != 200:
                error_message = f"Jina API returned status {response.status_code}: {response.text}"
                logger.error(error_message)
                return f"Error: {error_message}"

            if not response.text or not response.text.strip():
                error_message = "Jina API returned empty response"
                logger.error(error_message)
                return f"Error: {error_message}"

            return response.text
        except Exception as e:
            error_message = f"Request to Jina API failed: {type(e).__name__}: {e}"
            logger.warning(error_message)
            return f"Error: {error_message}"

import asyncio

from langchain.tools import tool

from deerflow.community.jina_ai.jina_client import JinaClient
from deerflow.config import get_app_config
from deerflow.utils.readability import ReadabilityExtractor

readability_extractor = ReadabilityExtractor()


def _coerce_bool(value: object, default: bool) -> bool:
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        normalized = value.strip().lower()
        if normalized in {"1", "true", "yes", "on"}:
            return True
        if normalized in {"0", "false", "no", "off"}:
            return False
    return default


def _coerce_timeout(value: object, default: int) -> int:
    if isinstance(value, bool):
        return default
    if isinstance(value, int):
        return value
    if isinstance(value, str):
        try:
            return int(value)
        except ValueError:
            return default
    return default


def _coerce_proxy(value: object) -> str | None:
    if not isinstance(value, str):
        return None
    proxy = value.strip()
    return proxy or None


@tool("web_fetch", parse_docstring=True)
async def web_fetch_tool(url: str) -> str:
    """Fetch the contents of a web page at a given URL.
    Only fetch EXACT URLs that have been provided directly by the user or have been returned in results from the web_search and web_fetch tools.
    This tool can NOT access content that requires authentication, such as private Google Docs or pages behind login walls.
    Do NOT add www. to URLs that do NOT have them.
    URLs must include the schema: https://example.com is a valid URL while example.com is an invalid URL.

    Args:
        url: The URL to fetch the contents of.
    """
    jina_client = JinaClient()
    timeout = 10
    proxy = None
    trust_env = True
    config = get_app_config().get_tool_config("web_fetch")
    if config is not None:
        timeout = _coerce_timeout(config.model_extra.get("timeout"), timeout)
        proxy = _coerce_proxy(config.model_extra.get("proxy"))
        trust_env = _coerce_bool(config.model_extra.get("trust_env"), trust_env)
    html_content = await jina_client.crawl(url, return_format="html", timeout=timeout, proxy=proxy, trust_env=trust_env)
    if isinstance(html_content, str) and html_content.startswith("Error:"):
        return html_content
    article = await asyncio.to_thread(readability_extractor.extract_article, html_content)
    return article.to_markdown()[:4096]

