"""Process-local LRU backend. Zero serialization on the hit path."""

from __future__ import annotations

from collections import OrderedDict
from typing import Any

from deerflow.runtime.checkpoint_cache.base import CheckpointCacheStats, thread_key_stem


def _copy_entry(entry: dict[str, Any]) -> dict[str, Any]:
    """Copy-on-read/write: fresh writes list; seed shared (never mutated in place)."""
    copied: dict[str, Any] = {"writes": list(entry["writes"])}
    if "seed" in entry:
        copied["seed"] = entry["seed"]
    return copied


class MemoryCheckpointHistoryCache:
    def __init__(self, max_entries: int = 128) -> None:
        if max_entries < 0:
            raise ValueError("max_entries must be >= 0")
        self._max_entries = max_entries
        self._data: OrderedDict[str, dict[str, Any]] = OrderedDict()
        self._hits = 0
        self._misses = 0
        self._evictions = 0

    @property
    def enabled(self) -> bool:
        return self._max_entries > 0

    def get_many(self, keys: list[str]) -> dict[str, dict[str, Any]]:
        found: dict[str, dict[str, Any]] = {}
        for key in keys:
            entry = self._data.get(key)
            if entry is None:
                self._misses += 1
                continue
            self._data.move_to_end(key)
            self._hits += 1
            found[key] = _copy_entry(entry)
        return found

    def set_many(self, entries: dict[str, dict[str, Any]]) -> None:
        if not self.enabled:
            return
        for key, entry in entries.items():
            self._data[key] = _copy_entry(entry)
            self._data.move_to_end(key)
            while len(self._data) > self._max_entries:
                self._data.popitem(last=False)
                self._evictions += 1

    async def aget_many(self, keys: list[str]) -> dict[str, dict[str, Any]]:
        return self.get_many(keys)

    async def aset_many(self, entries: dict[str, dict[str, Any]]) -> None:
        self.set_many(entries)

    def delete_thread(self, key_prefix: str, thread_id: str) -> None:
        """Purge every entry of one thread (lifecycle, not invalidation)."""
        stem = thread_key_stem(key_prefix, thread_id)
        for key in [k for k in self._data if k.startswith(stem)]:
            del self._data[key]

    async def adelete_thread(self, key_prefix: str, thread_id: str) -> None:
        self.delete_thread(key_prefix, thread_id)

    def stats(self) -> CheckpointCacheStats:
        return CheckpointCacheStats(
            hits=self._hits,
            misses=self._misses,
            evictions=self._evictions,
            entries=len(self._data),
        )

    async def aclose(self) -> None:
        self._data.clear()

"""Shared Redis backend. Entries are immutable, so a multi-worker shared
cache needs no invalidation; the TTL is a leak safety net only.

Thread-scoped purge (``adelete_thread``) exists for data lifecycle: when a
thread's checkpoints are deleted, its cached history payloads are removed
immediately instead of lingering until TTL expiry.

The redis import is lazy (module is importable without the optional
``redis`` extra), mirroring runtime/stream_bridge/redis.py.
"""

from __future__ import annotations

import logging
from typing import Any

from deerflow.runtime.checkpoint_cache.base import CheckpointCacheStats, thread_key_stem

logger = logging.getLogger(__name__)

REDIS_INSTALL = "redis is required for the redis checkpoint cache backend. Install it with: uv sync --extra redis"

_TAG_SEPARATOR = b"\x00"


def _create_client(redis_url: str, *, max_connections: int | None) -> Any:
    try:
        import redis.asyncio as redis_async
    except ImportError as exc:
        raise ImportError(REDIS_INSTALL) from exc
    kwargs: dict[str, Any] = {"decode_responses": False}
    if max_connections is not None:
        kwargs["max_connections"] = max_connections
    return redis_async.from_url(redis_url, **kwargs)


def _redis_error() -> type[Exception]:
    """Lazy RedisError import, mirroring the lazy client creation above."""
    try:
        from redis.exceptions import RedisError
    except ImportError as exc:
        raise ImportError(REDIS_INSTALL) from exc
    return RedisError


class RedisCheckpointHistoryCache:
    def __init__(
        self,
        redis_url: str,
        *,
        serde: Any,
        ttl_seconds: int,
        max_connections: int | None = None,
    ) -> None:
        self._client = _create_client(redis_url, max_connections=max_connections)
        self._serde = serde
        # ttl_seconds=0 is an explicit opt-out of expiry (no SETEX) — not the
        # default, and leaked/orphaned keys then rely on redis maxmemory only.
        self._ttl = ttl_seconds if ttl_seconds > 0 else None
        self._hits = 0
        self._misses = 0

    async def aget_many(self, keys: list[str]) -> dict[str, dict[str, Any]]:
        if not keys:
            return {}
        try:
            raws = await self._client.mget(keys)
        except _redis_error() as exc:
            # Performance-only bypass: a redis outage costs hits, never availability.
            logger.warning("checkpoint history cache mget failed; treating as all-miss: %s", exc)
            self._misses += len(keys)
            return {}
        found: dict[str, dict[str, Any]] = {}
        for key, raw in zip(keys, raws, strict=True):
            if raw is None:
                self._misses += 1
                continue
            self._hits += 1
            tag, payload = raw.split(_TAG_SEPARATOR, 1)
            found[key] = self._serde.loads_typed((tag.decode(), payload))
        return found

    async def aset_many(self, entries: dict[str, dict[str, Any]]) -> None:
        if not entries:
            return
        try:
            pipe = self._client.pipeline(transaction=False)
            for key, entry in entries.items():
                tag, data = self._serde.dumps_typed(entry)
                pipe.set(key, tag.encode() + _TAG_SEPARATOR + data, ex=self._ttl)
            await pipe.execute()
        except _redis_error() as exc:
            # Writes are optional; the next read simply recomputes the history.
            logger.warning("checkpoint history cache write failed; skipping: %s", exc)

    async def adelete_thread(self, key_prefix: str, thread_id: str) -> None:
        """SCAN+UNLINK every entry of one thread. Failure degrades to
        TTL-bounded residual retention; the source-of-truth delete already
        happened, so this never raises."""
        stem = thread_key_stem(key_prefix, thread_id)
        try:
            cursor = 0
            while True:
                cursor, keys = await self._client.scan(cursor=cursor, match=stem + "*", count=500)
                if keys:
                    await self._client.unlink(*keys)
                if cursor == 0:
                    break
        except _redis_error() as exc:
            logger.warning("checkpoint history cache thread purge failed; residual entries expire via TTL: %s", exc)

    def stats(self) -> CheckpointCacheStats:
        return CheckpointCacheStats(hits=self._hits, misses=self._misses)

    async def aclose(self) -> None:
        await self._client.aclose()

"""Dual-mode checkpoint channel safety: mode freeze, metadata markers, and the fail-closed gate.

Checkpointer storage runs in ``full`` mode (whole-snapshot channel values) or
``delta`` mode (LangGraph ``DeltaChannel``: sentinel blobs + per-step writes).
The mode is process-frozen at agent-build time, stamped into each checkpoint's
metadata on write, and enforced before every state access: a full-mode process
opening a delta thread raises :class:`CheckpointModeMismatchError` instead of
silently materializing empty state. Delta-mode processes read legacy full
checkpoints transparently, so full -> delta is the supported migration path.
"""

from __future__ import annotations

from typing import Any

from deerflow.config.database_config import DEFAULT_CHECKPOINT_SNAPSHOT_FREQUENCY, CheckpointChannelMode

INTERNAL_CHECKPOINT_MODE_KEY = "__deerflow_checkpoint_channel_mode"
CHECKPOINT_MODE_METADATA_KEY = "deerflow_checkpoint_channel_mode"


class CheckpointModeMismatchError(RuntimeError):
    """Raised before a full-mode graph reads a Delta checkpoint."""


class CheckpointModeReconfigurationError(RuntimeError):
    """Raised when a process attempts to hot-switch its persistence mode."""


_frozen_checkpoint_channel_mode: CheckpointChannelMode | None = None
_frozen_checkpoint_snapshot_frequency: int | None = None


def frozen_checkpoint_channel_mode() -> CheckpointChannelMode | None:
    """Return the process-frozen checkpoint channel mode, if already frozen."""
    return _frozen_checkpoint_channel_mode


def freeze_checkpoint_channel_mode(mode: CheckpointChannelMode) -> CheckpointChannelMode:
    global _frozen_checkpoint_channel_mode
    if _frozen_checkpoint_channel_mode is None:
        _frozen_checkpoint_channel_mode = mode
    elif _frozen_checkpoint_channel_mode != mode:
        raise CheckpointModeReconfigurationError("checkpoint_channel_mode is restart-required and cannot change in a running process")
    return _frozen_checkpoint_channel_mode


def frozen_checkpoint_snapshot_frequency() -> int | None:
    """Return the process-frozen delta snapshot frequency, if already frozen."""
    return _frozen_checkpoint_snapshot_frequency


def freeze_checkpoint_snapshot_frequency(snapshot_frequency: int) -> int:
    """Freeze the delta snapshot cadence alongside the channel mode.

    The cadence is compiled into each graph's channel table, so like the
    mode it is restart-required and must match across every process sharing
    one checkpoint database. It is deliberately NOT stamped into checkpoint
    metadata: the mode marker contract (absence = full) and the full ->
    delta migration semantics are unchanged by the frequency value.
    """
    global _frozen_checkpoint_snapshot_frequency
    if snapshot_frequency <= 0:
        raise ValueError("snapshot frequency must be positive")
    if _frozen_checkpoint_snapshot_frequency is None:
        _frozen_checkpoint_snapshot_frequency = snapshot_frequency
    elif _frozen_checkpoint_snapshot_frequency != snapshot_frequency:
        raise CheckpointModeReconfigurationError("checkpoint_delta.snapshot_frequency is restart-required and cannot change in a running process")
    return _frozen_checkpoint_snapshot_frequency


def resolve_checkpoint_snapshot_frequency(snapshot_frequency: int | None = None) -> int:
    """Resolve the effective snapshot frequency: explicit value, else the
    process-frozen value, else the config default."""
    if snapshot_frequency is not None:
        return snapshot_frequency
    frozen = _frozen_checkpoint_snapshot_frequency
    return frozen if frozen is not None else DEFAULT_CHECKPOINT_SNAPSHOT_FREQUENCY


def inject_checkpoint_mode(config: dict[str, Any], mode: CheckpointChannelMode) -> None:
    configurable = config.setdefault("configurable", {})
    configurable[INTERNAL_CHECKPOINT_MODE_KEY] = mode
    metadata = config.setdefault("metadata", {})
    if mode == "delta":
        metadata[CHECKPOINT_MODE_METADATA_KEY] = "delta"
    else:
        metadata.pop(CHECKPOINT_MODE_METADATA_KEY, None)


def checkpoint_metadata_uses_delta(metadata: Any) -> bool:
    """Whether checkpoint metadata carries the delta-mode marker."""
    if not metadata:
        return False
    if metadata.get(CHECKPOINT_MODE_METADATA_KEY) == "delta":
        return True
    counters = metadata.get("counters_since_delta_snapshot")
    return isinstance(counters, dict) and "messages" in counters


def checkpoint_tuple_uses_delta(checkpoint_tuple: Any) -> bool:
    if checkpoint_tuple is None:
        return False
    return checkpoint_metadata_uses_delta(getattr(checkpoint_tuple, "metadata", {}) or {})


def state_snapshot_uses_delta(snapshot: Any) -> bool:
    """Whether a materialized ``StateSnapshot`` originates from a delta checkpoint."""
    if snapshot is None:
        return False
    return checkpoint_metadata_uses_delta(getattr(snapshot, "metadata", {}) or {})


def raise_if_snapshot_incompatible(snapshot: Any, mode: CheckpointChannelMode) -> None:
    """Fail closed when a full-mode process materialized a delta checkpoint.

    Runs on the ``StateSnapshot`` returned by ``get_state``/``get_state_history``,
    so reads cost a single checkpoint fetch: the marker lives in
    ``snapshot.metadata``. Reading the blob is harmless; silently *using* the
    empty/partial state is the danger, and the caller never receives it.
    """
    if mode == "full" and state_snapshot_uses_delta(snapshot):
        raise CheckpointModeMismatchError("Thread requires delta mode; materialize and convert its checkpoints before using full mode.")


def ensure_checkpoint_mode_compatible(checkpointer: Any, config: dict[str, Any], mode: CheckpointChannelMode) -> None:
    """Pre-write gate: a write cannot be un-applied, so it checks ahead of time.

    Reads use :func:`raise_if_snapshot_incompatible` on the returned snapshot
    instead, avoiding the extra fetch.
    """
    if mode == "delta":
        return
    if checkpoint_tuple_uses_delta(checkpointer.get_tuple(config)):
        raise CheckpointModeMismatchError("Thread requires delta mode; materialize and convert its checkpoints before using full mode.")


async def aensure_checkpoint_mode_compatible(checkpointer: Any, config: dict[str, Any], mode: CheckpointChannelMode) -> None:
    if mode == "delta":
        return
    if checkpoint_tuple_uses_delta(await checkpointer.aget_tuple(config)):
        raise CheckpointModeMismatchError("Thread requires delta mode; materialize and convert its checkpoints before using full mode.")

"""Read-through delta-history cache wrapper for any BaseCheckpointSaver.

Correctness argument (spec §3): a checkpoint's delta history is a pure
function of its sealed ancestor chain — the LangGraph contract excludes the
target's own pending writes, parent links are fixed at creation, and an
ancestor's writes are sealed once its child exists. Entries keyed by
(thread, ns, checkpoint_id, channel) are therefore immutable: no
invalidation, and shared backends are coherent across processes.

The wrapper never caches the "latest checkpoint" resolution; only histories
keyed by resolved immutable checkpoint_ids.

Data lifecycle: thread deletion and prune purge the thread's cached entries
(source-of-truth removal must not leave residual history payloads in the
cache); run-scoped deletes cannot be mapped to threads cheaply and rely on
LRU/TTL bounds.
"""

from __future__ import annotations

import logging
from collections.abc import Iterator, Sequence
from typing import Any

from langchain_core.runnables import RunnableConfig
from langgraph.checkpoint.base import BaseCheckpointSaver, CheckpointTuple, PendingWrite

from deerflow.runtime.checkpoint_cache.base import make_history_key

logger = logging.getLogger(__name__)

# Depth budget for recursive compose before falling back to a chain-warming
# walk. Steady-state runs need ~2 (one intermediate checkpoint per step);
# deeper cold chains are handled faster by one warming walk than by many
# recursive single-tuple fetches.
_COMPOSE_MAX_DEPTH = 8


def _checkpoint_ref(tup: CheckpointTuple) -> tuple[str, str, str]:
    configurable = tup.config["configurable"]
    return (
        str(configurable["thread_id"]),
        str(configurable.get("checkpoint_ns", "")),
        str(configurable["checkpoint_id"]),
    )


def _channel_writes(tup: CheckpointTuple, channel: str) -> list[PendingWrite]:
    """Writes for one channel, oldest→newest (tuple storage order)."""
    return [w for w in (tup.pending_writes or []) if w[1] == channel]


class CachedHistorySaver(BaseCheckpointSaver):
    def __init__(self, inner: BaseCheckpointSaver, cache: Any, *, key_prefix: str) -> None:
        # Instance attr shadows the base class JsonPlusSerializer default.
        self.serde = inner.serde
        self._inner = inner
        self._cache = cache
        self._key_prefix = key_prefix
        self._compose_hits = 0
        self._full_walks = 0

    def __getattr__(self, name: str) -> Any:
        # Safety net for saver-specific extras (e.g. AsyncSqliteSaver.setup).
        # Base-class methods are explicitly delegated below, so this only
        # fires for attributes BaseCheckpointSaver does not define.
        inner = self.__dict__.get("_inner")
        if inner is None:
            raise AttributeError(name)
        return getattr(inner, name)

    # ------------------------------------------------------------------
    # Key building
    # ------------------------------------------------------------------

    def _key(self, tup: CheckpointTuple, channel: str) -> str:
        thread_id, ns, checkpoint_id = _checkpoint_ref(tup)
        return make_history_key(self._key_prefix, thread_id, ns, checkpoint_id, channel)

    # ------------------------------------------------------------------
    # Stats
    # ------------------------------------------------------------------

    def stats(self) -> dict[str, int]:
        backend = self._cache.stats().as_dict()
        return {**backend, "compose_hits": self._compose_hits, "full_walks": self._full_walks}

    # ------------------------------------------------------------------
    # Delta history: the only overridden behavior
    # ------------------------------------------------------------------

    async def aget_delta_channel_history(self, *, config: RunnableConfig, channels: Sequence[str]) -> dict[str, Any]:
        if not channels:
            return {}
        if not getattr(self._cache, "enabled", True):
            # Disabled cache: pass straight through; composing over all-miss
            # entries is strictly more work than the raw saver's walk.
            return await self._walk_inner(config, channels)
        target = await self._inner.aget_tuple(config)
        if target is None:
            return await self._walk_inner(config, channels)

        keys = {ch: self._key(target, ch) for ch in channels}
        hits = await self._cache.aget_many(list(keys.values()))
        found: dict[str, dict[str, Any]] = {}
        missing: list[str] = []
        for ch in channels:
            entry = hits.get(keys[ch])
            if entry is None:
                missing.append(ch)
            else:
                found[ch] = entry

        computed: dict[str, dict[str, Any]] = {}
        if missing:
            computed = await self._compose_or_walk(config, target, missing)

        new_entries = {keys[ch]: computed[ch] for ch in missing if ch in computed}
        if new_entries:
            await self._cache.aset_many(new_entries)

        return {ch: found.get(ch) or computed.get(ch) or {"writes": []} for ch in channels}

    async def _compose_or_walk(self, config: RunnableConfig, target: CheckpointTuple, missing: list[str]) -> dict[str, dict[str, Any]]:
        return {ch: await self._aresolve(target, ch, _COMPOSE_MAX_DEPTH) for ch in missing}

    async def _aresolve(self, tup: CheckpointTuple, channel: str, depth: int) -> dict[str, Any]:
        """Recursively compose history(tup) from the nearest warm ancestor.

        Real runs create several checkpoints per super-step and only some are
        ever materialized as targets, so the parent is usually an unwarmed
        intermediate checkpoint (measured: 0 cache hits with single-level
        compose on a 500-step sqlite run). Recursing one level per
        intermediate lands on a warmed ancestor within ~2 levels in steady
        state; each composed level is cached, so the warm frontier follows
        the run. At depth 0 on a cold chain it delegates one inner fast-path
        walk (2 SQL) rather than crawling ancestors tuple-by-tuple.
        """
        parent_config = tup.parent_config
        if parent_config is None:
            return {"writes": []}
        parent = await self._inner.aget_tuple(parent_config)
        if parent is None:
            return {"writes": []}

        channel_values = parent.checkpoint.get("channel_values") or {}
        writes = _channel_writes(parent, channel)
        if channel in channel_values:
            self._compose_hits += 1
            return {"writes": writes, "seed": channel_values[channel]}

        key = self._key(parent, channel)
        hits = await self._cache.aget_many([key])
        parent_history = hits.get(key)
        if parent_history is None:
            if depth > 0:
                parent_history = await self._aresolve(parent, channel, depth - 1)
            else:
                # Depth budget exhausted on a cold chain: delegate ONE inner
                # fast-path walk (2 SQL total) for this level instead of
                # fetching every ancestor tuple individually. Ancestors below
                # stay cold; resolving them later recurses up to the nearest
                # warm level, so the frontier still follows the run.
                self._full_walks += 1
                walked = await self._inner.aget_delta_channel_history(config=parent.config, channels=[channel])
                parent_history = walked.get(channel) or {"writes": []}
            if parent_history is not None:
                await self._cache.aset_many({key: parent_history})

        self._compose_hits += 1
        entry: dict[str, Any] = {"writes": list(parent_history["writes"]) + writes}
        if "seed" in parent_history:
            entry["seed"] = parent_history["seed"]
        return entry

    async def _walk_inner(self, config: RunnableConfig, channels: Sequence[str]) -> dict[str, Any]:
        self._full_walks += 1
        return dict(await self._inner.aget_delta_channel_history(config=config, channels=channels))

    def get_delta_channel_history(self, *, config: RunnableConfig, channels: Sequence[str]) -> dict[str, Any]:
        if not channels:
            return {}
        if not getattr(self._cache, "enabled", True):
            return self._walk_inner_sync(config, channels)
        get_many = getattr(self._cache, "get_many", None)
        set_many = getattr(self._cache, "set_many", None)
        if get_many is None or set_many is None:
            raise TypeError("sync get_delta_channel_history requires a SyncCheckpointHistoryCache (memory backend)")
        target = self._inner.get_tuple(config)
        if target is None:
            return self._walk_inner_sync(config, channels)

        keys = {ch: self._key(target, ch) for ch in channels}
        hits = get_many(list(keys.values()))
        found: dict[str, dict[str, Any]] = {}
        missing: list[str] = []
        for ch in channels:
            entry = hits.get(keys[ch])
            if entry is None:
                missing.append(ch)
            else:
                found[ch] = entry

        computed: dict[str, dict[str, Any]] = {}
        if missing:
            computed = {ch: self._resolve_sync(target, ch, _COMPOSE_MAX_DEPTH) for ch in missing}

        new_entries = {keys[ch]: computed[ch] for ch in missing if ch in computed}
        if new_entries:
            set_many(new_entries)
        return {ch: found.get(ch) or computed.get(ch) or {"writes": []} for ch in channels}

    def _resolve_sync(self, tup: CheckpointTuple, channel: str, depth: int) -> dict[str, Any]:
        """Sync twin of _aresolve (recursive compose, see its docstring)."""
        parent_config = tup.parent_config
        if parent_config is None:
            return {"writes": []}
        parent = self._inner.get_tuple(parent_config)
        if parent is None:
            return {"writes": []}

        channel_values = parent.checkpoint.get("channel_values") or {}
        writes = _channel_writes(parent, channel)
        if channel in channel_values:
            self._compose_hits += 1
            return {"writes": writes, "seed": channel_values[channel]}

        key = self._key(parent, channel)
        parent_history = self._cache.get_many([key]).get(key)
        if parent_history is None:
            if depth > 0:
                parent_history = self._resolve_sync(parent, channel, depth - 1)
            else:
                # See _aresolve: one inner fast-path walk, no per-tuple crawl.
                self._full_walks += 1
                parent_history = self._inner.get_delta_channel_history(config=parent.config, channels=[channel]).get(channel) or {"writes": []}
            if parent_history is not None:
                self._cache.set_many({key: parent_history})

        self._compose_hits += 1
        entry: dict[str, Any] = {"writes": list(parent_history["writes"]) + writes}
        if "seed" in parent_history:
            entry["seed"] = parent_history["seed"]
        return entry

    def _walk_inner_sync(self, config: RunnableConfig, channels: Sequence[str]) -> dict[str, Any]:
        self._full_walks += 1
        return dict(self._inner.get_delta_channel_history(config=config, channels=channels))

    # ------------------------------------------------------------------
    # Explicit delegation (BaseCheckpointSaver defines these concretely,
    # so __getattr__ never fires for them)
    # ------------------------------------------------------------------

    def get_tuple(self, config: RunnableConfig) -> CheckpointTuple | None:
        return self._inner.get_tuple(config)

    def list(self, config: RunnableConfig | None, *, filter: dict[str, Any] | None = None, before: RunnableConfig | None = None, limit: int | None = None) -> Iterator[CheckpointTuple]:
        return self._inner.list(config, filter=filter, before=before, limit=limit)

    def put(self, config: RunnableConfig, checkpoint: dict[str, Any], metadata: dict[str, Any], new_versions: dict[str, Any]) -> RunnableConfig:
        return self._inner.put(config, checkpoint, metadata, new_versions)

    def put_writes(self, config: RunnableConfig, writes: Sequence[tuple[str, str, Any]], task_id: str, task_path: str = "") -> None:
        self._inner.put_writes(config, writes, task_id, task_path)

    def delete_thread(self, thread_id: str) -> None:
        self._inner.delete_thread(thread_id)
        self._purge_thread_sync(thread_id)

    def delete_for_runs(self, run_ids: Sequence[str]) -> None:
        # Run-scoped deletes cannot be mapped back to threads without an extra
        # query, so cached entries are left in place: they stay *correct* (the
        # sealed-chain argument is unaffected by other chains) and residual
        # retention is bounded by LRU/TTL. No in-tree callers today.
        self._inner.delete_for_runs(run_ids)

    def _purge_thread_sync(self, thread_id: str) -> None:
        delete = getattr(self._cache, "delete_thread", None)
        if delete is not None:
            delete(self._key_prefix, thread_id)

    def copy_thread(self, source_thread_id: str, target_thread_id: str) -> None:
        self._inner.copy_thread(source_thread_id, target_thread_id)

    def prune(self, thread_ids: Sequence[str], *, strategy: str = "keep_latest") -> None:
        self._inner.prune(thread_ids, strategy=strategy)
        # Pruning rewrites these threads' chains: purge so no cached history
        # references a deleted ancestor (retention) or its pre-prune chain.
        for thread_id in thread_ids:
            self._purge_thread_sync(thread_id)

    async def aget_tuple(self, config: RunnableConfig) -> CheckpointTuple | None:
        return await self._inner.aget_tuple(config)

    def alist(self, config: RunnableConfig | None, *, filter: dict[str, Any] | None = None, before: RunnableConfig | None = None, limit: int | None = None) -> Any:
        return self._inner.alist(config, filter=filter, before=before, limit=limit)

    async def aput(self, config: RunnableConfig, checkpoint: dict[str, Any], metadata: dict[str, Any], new_versions: dict[str, Any]) -> RunnableConfig:
        return await self._inner.aput(config, checkpoint, metadata, new_versions)

    async def aput_writes(self, config: RunnableConfig, writes: Sequence[tuple[str, str, Any]], task_id: str, task_path: str = "") -> None:
        await self._inner.aput_writes(config, writes, task_id, task_path)

    async def adelete_thread(self, thread_id: str) -> None:
        await self._inner.adelete_thread(thread_id)
        await self._apurge_thread(thread_id)

    async def adelete_for_runs(self, run_ids: Sequence[str]) -> None:
        # See delete_for_runs: unscoped residual retention bounded by LRU/TTL.
        await self._inner.adelete_for_runs(run_ids)

    async def _apurge_thread(self, thread_id: str) -> None:
        delete = getattr(self._cache, "adelete_thread", None)
        if delete is not None:
            await delete(self._key_prefix, thread_id)

    async def acopy_thread(self, source_thread_id: str, target_thread_id: str) -> None:
        await self._inner.acopy_thread(source_thread_id, target_thread_id)

    async def aprune(self, thread_ids: Sequence[str], *, strategy: str = "keep_latest") -> None:
        await self._inner.aprune(thread_ids, strategy=strategy)
        # See prune: rewritten chains must not keep pre-prune cached histories.
        for thread_id in thread_ids:
            await self._apurge_thread(thread_id)

    def get_next_version(self, current: Any, channel: Any) -> Any:
        return self._inner.get_next_version(current, channel)

"""Pure functions to convert LangChain message objects to OpenAI Chat Completions format.

Utility for translating LangChain message types to OpenAI-compatible dicts.
Not currently wired into RunJournal (which uses message.model_dump() directly),
but available for consumers that need the OpenAI wire format.
"""

from __future__ import annotations

import json
from typing import Any

_ROLE_MAP = {
    "human": "user",
    "ai": "assistant",
    "system": "system",
    "tool": "tool",
}


def langchain_to_openai_message(message: Any) -> dict:
    """Convert a single LangChain BaseMessage to an OpenAI message dict.

    Handles:
    - HumanMessage → {"role": "user", "content": "..."}
    - AIMessage (text only) → {"role": "assistant", "content": "..."}
    - AIMessage (with tool_calls) → {"role": "assistant", "content": null, "tool_calls": [...]}
    - AIMessage (text + tool_calls) → both content and tool_calls present
    - AIMessage (list content / multimodal) → content preserved as list
    - SystemMessage → {"role": "system", "content": "..."}
    - ToolMessage → {"role": "tool", "tool_call_id": "...", "content": "..."}
    """
    msg_type = getattr(message, "type", "")
    role = _ROLE_MAP.get(msg_type, msg_type)
    content = getattr(message, "content", "")

    if role == "tool":
        return {
            "role": "tool",
            "tool_call_id": getattr(message, "tool_call_id", ""),
            "content": content,
        }

    if role == "assistant":
        tool_calls = getattr(message, "tool_calls", None) or []
        result: dict = {"role": "assistant"}

        if tool_calls:
            openai_tool_calls = []
            for tc in tool_calls:
                args = tc.get("args", {})
                openai_tool_calls.append(
                    {
                        "id": tc.get("id", ""),
                        "type": "function",
                        "function": {
                            "name": tc.get("name", ""),
                            "arguments": json.dumps(args) if not isinstance(args, str) else args,
                        },
                    }
                )
            # If no text content, set content to null per OpenAI spec
            result["content"] = content if (isinstance(content, list) and content) or (isinstance(content, str) and content) else None
            result["tool_calls"] = openai_tool_calls
        else:
            result["content"] = content

        return result

    # user / system / unknown
    return {"role": role, "content": content}


def _infer_finish_reason(message: Any) -> str:
    """Infer OpenAI finish_reason from an AIMessage.

    Returns "tool_calls" if tool_calls present, else looks in
    response_metadata.finish_reason, else returns "stop".
    """
    tool_calls = getattr(message, "tool_calls", None) or []
    if tool_calls:
        return "tool_calls"
    resp_meta = getattr(message, "response_metadata", None) or {}
    if isinstance(resp_meta, dict):
        finish = resp_meta.get("finish_reason")
        if finish:
            return finish
    return "stop"


def langchain_to_openai_completion(message: Any) -> dict:
    """Convert an AIMessage and its metadata to an OpenAI completion response dict.

    Returns:
        {
            "id": message.id,
            "model": message.response_metadata.get("model_name"),
            "choices": [{"index": 0, "message": <openai_message>, "finish_reason": <inferred>}],
            "usage": {"prompt_tokens": ..., "completion_tokens": ..., "total_tokens": ...} or None,
        }
    """
    resp_meta = getattr(message, "response_metadata", None) or {}
    model_name = resp_meta.get("model_name") if isinstance(resp_meta, dict) else None

    openai_msg = langchain_to_openai_message(message)
    finish_reason = _infer_finish_reason(message)

    usage_metadata = getattr(message, "usage_metadata", None)
    if usage_metadata is not None:
        input_tokens = usage_metadata.get("input_tokens", 0) or 0
        output_tokens = usage_metadata.get("output_tokens", 0) or 0
        usage: dict | None = {
            "prompt_tokens": input_tokens,
            "completion_tokens": output_tokens,
            "total_tokens": input_tokens + output_tokens,
        }
    else:
        usage = None

    return {
        "id": getattr(message, "id", None),
        "model": model_name,
        "choices": [
            {
                "index": 0,
                "message": openai_msg,
                "finish_reason": finish_reason,
            }
        ],
        "usage": usage,
    }


def langchain_messages_to_openai(messages: list) -> list[dict]:
    """Convert a list of LangChain BaseMessages to OpenAI message dicts."""
    return [langchain_to_openai_message(m) for m in messages]

from deerflow.runtime.events.store.base import RunEventStore
from deerflow.runtime.events.store.memory import MemoryRunEventStore


def make_run_event_store(config=None) -> RunEventStore:
    """Create a RunEventStore based on run_events.backend configuration."""
    if config is None or config.backend == "memory":
        return MemoryRunEventStore()
    if config.backend == "db":
        from deerflow.persistence.engine import get_session_factory

        sf = get_session_factory()
        if sf is None:
            # database.backend=memory but run_events.backend=db -> fallback
            return MemoryRunEventStore()
        from deerflow.runtime.events.store.db import DbRunEventStore

        return DbRunEventStore(sf, max_trace_content=config.max_trace_content)
    if config.backend == "jsonl":
        from deerflow.runtime.events.store.jsonl import JsonlRunEventStore

        return JsonlRunEventStore()
    raise ValueError(f"Unknown run_events backend: {config.backend!r}")


__all__ = ["MemoryRunEventStore", "RunEventStore", "make_run_event_store"]

"""Run naming helpers for LangChain/LangSmith tracing."""

from __future__ import annotations

from collections.abc import Mapping
from typing import Any


def resolve_root_run_name(config: Mapping[str, Any], assistant_id: str | None) -> str:
    for container_name in ("context", "configurable"):
        container = config.get(container_name)
        if isinstance(container, Mapping):
            agent_name = container.get("agent_name")
            if isinstance(agent_name, str) and agent_name.strip():
                return agent_name
    return assistant_id or "lead_agent"

"""Canonical serialization for LangChain / LangGraph objects.

Provides a single source of truth for converting LangChain message
objects, Pydantic models, and LangGraph state dicts into plain
JSON-serialisable Python structures.

Consumers: ``deerflow.runtime.runs.worker`` (SSE publishing) and
``app.gateway.routers.threads`` (REST responses).
"""

from __future__ import annotations

from typing import Any


def serialize_lc_object(obj: Any) -> Any:
    """Recursively serialize a LangChain object to a JSON-serialisable dict."""
    if obj is None:
        return None
    if isinstance(obj, (str, int, float, bool)):
        return obj
    if isinstance(obj, dict):
        return {k: serialize_lc_object(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple)):
        return [serialize_lc_object(item) for item in obj]
    # Pydantic v2
    if hasattr(obj, "model_dump"):
        try:
            return obj.model_dump()
        except Exception:
            pass
    # Pydantic v1 / older objects
    if hasattr(obj, "dict"):
        try:
            return obj.dict()
        except Exception:
            pass
    # Interrupt is a __slots__ class — no model_dump/dict/__dict__, so it
    # would reach str() and produce a malformed payload.
    try:
        from langgraph.types import Interrupt
    except ImportError:
        pass
    else:
        if isinstance(obj, Interrupt):
            return serialize_lc_object(
                {
                    "value": obj.value,
                    "id": getattr(obj, "id", None),
                }
            )
    # Last resort
    try:
        return str(obj)
    except Exception:
        return repr(obj)


def serialize_channel_values(channel_values: dict[str, Any]) -> dict[str, Any]:
    """Serialize channel values, stripping internal LangGraph keys.

    Only ``__pregel_*`` keys are removed — ``__interrupt__`` is deliberately
    preserved so the LangGraph SDK can detect interrupt events from values
    chunks (see issue #3595).
    """
    result: dict[str, Any] = {}
    for key, value in channel_values.items():
        if key.startswith("__pregel_"):
            continue
        result[key] = serialize_lc_object(value)
    return result


def strip_data_url_image_blocks(messages: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Remove ``data:``-scheme ``image_url`` blocks from *hide_from_ui* messages.

    The history and run-wait endpoints return checkpoint-persisted messages to
    the frontend.  ``ViewImageMiddleware`` now keeps its base64 image payloads
    inside the model request, but threads checkpointed by earlier versions still
    hold them in ``hide_from_ui`` human messages — these are internal model
    context and must not be sent over the wire (huge response bodies, no UI
    value).

    Only content blocks of type ``image_url`` whose URL starts with ``data:``
    are stripped.  Text blocks, ``https://`` image URLs, and non-hidden
    messages are left untouched so that message ordering and count are
    preserved.
    """
    result: list[dict[str, Any]] = []
    for msg in messages:
        if not isinstance(msg, dict):
            result.append(msg)
            continue

        # Only touch messages explicitly flagged as hidden from the UI.
        additional_kwargs = msg.get("additional_kwargs")
        if not (isinstance(additional_kwargs, dict) and additional_kwargs.get("hide_from_ui") is True):
            result.append(msg)
            continue

        content = msg.get("content")
        if not isinstance(content, list):
            result.append(msg)
            continue

        # Filter out image_url blocks with data: scheme.
        filtered = [block for block in content if not (isinstance(block, dict) and block.get("type") == "image_url" and isinstance(block.get("image_url"), dict) and str(block["image_url"].get("url", "")).startswith("data:"))]
        result.append({**msg, "content": filtered})
    return result


def serialize_channel_values_for_api(channel_values: dict[str, Any]) -> dict[str, Any]:
    """Serialize channel values and strip base64 image data from messages.

    Convenience wrapper combining :func:`serialize_channel_values` with
    :func:`strip_data_url_image_blocks`.  Use this in all REST endpoints
    that return channel values to the frontend so that ``data:``-scheme
    base64 image payloads are never sent over the wire.
    """
    result = serialize_channel_values(channel_values)
    if isinstance(result.get("messages"), list):
        result["messages"] = strip_data_url_image_blocks(result["messages"])
    return result


def serialize_messages_tuple(obj: Any) -> Any:
    """Serialize a messages-mode tuple ``(chunk, metadata)``."""
    if isinstance(obj, tuple) and len(obj) == 2:
        chunk, metadata = obj
        return [serialize_lc_object(chunk), metadata if isinstance(metadata, dict) else {}]
    return serialize_lc_object(obj)


def serialize(obj: Any, *, mode: str = "") -> Any:
    """Serialize LangChain objects with mode-specific handling.

    * ``messages`` — obj is ``(message_chunk, metadata_dict)``
    * ``values`` — obj is the full state dict; ``__pregel_*`` keys stripped and
      base64 ``data:`` image blocks dropped from hide_from_ui messages
    * everything else — recursive ``model_dump()`` / ``dict()`` fallback
    """
    if mode == "messages":
        return serialize_messages_tuple(obj)
    if mode == "values":
        # ``values`` snapshots stream the full state to the frontend, so they
        # must drop base64 image payloads the same way the REST endpoints do.
        return serialize_channel_values_for_api(obj) if isinstance(obj, dict) else serialize_lc_object(obj)
    return serialize_lc_object(obj)

"""Sandbox-related exceptions with structured error information."""


class SandboxError(Exception):
    """Base exception for all sandbox-related errors."""

    def __init__(self, message: str, details: dict | None = None):
        super().__init__(message)
        self.message = message
        self.details = details or {}

    def __str__(self) -> str:
        if self.details:
            detail_str = ", ".join(f"{k}={v}" for k, v in self.details.items())
            return f"{self.message} ({detail_str})"
        return self.message


class SandboxNotFoundError(SandboxError):
    """Raised when a sandbox cannot be found or is not available."""

    def __init__(self, message: str = "Sandbox not found", sandbox_id: str | None = None):
        details = {"sandbox_id": sandbox_id} if sandbox_id else None
        super().__init__(message, details)
        self.sandbox_id = sandbox_id


class SandboxRuntimeError(SandboxError):
    """Raised when sandbox runtime is not available or misconfigured."""

    pass


class SandboxCommandError(SandboxError):
    """Raised when a command execution fails in the sandbox."""

    def __init__(self, message: str, command: str | None = None, exit_code: int | None = None):
        details = {}
        if command:
            details["command"] = command[:100] + "..." if len(command) > 100 else command
        if exit_code is not None:
            details["exit_code"] = exit_code
        super().__init__(message, details)
        self.command = command
        self.exit_code = exit_code


class SandboxFileError(SandboxError):
    """Raised when a file operation fails in the sandbox."""

    def __init__(self, message: str, path: str | None = None, operation: str | None = None):
        details = {}
        if path:
            details["path"] = path
        if operation:
            details["operation"] = operation
        super().__init__(message, details)
        self.path = path
        self.operation = operation


class SandboxPermissionError(SandboxFileError):
    """Raised when a permission error occurs during file operations."""

    pass


class SandboxFileNotFoundError(SandboxFileError):
    """Raised when a file or directory is not found."""

    pass


class SandboxCapacityExceededError(SandboxError):
    """Raised when the sandbox provider has no available capacity.

    The reason distinguishes occupied capacity from provider shutdown.
    The caller controls retry scheduling. DeerFlow does not retry automatically.
    """

    CODE = "SANDBOX_CAPACITY_EXCEEDED"

    def __init__(
        self,
        message: str = "All sandbox replica slots are in use",
        *,
        active: int = 0,
        warm: int = 0,
        reserved: int = 0,
        replicas: int = 0,
        retry_after_seconds: float = 5.0,
        reason: str = "capacity",
    ) -> None:
        details: dict[str, object] = {
            "code": self.CODE,
            "reason": reason,
            "replicas": replicas,
            "retryable": True,
            "retry_after_seconds": retry_after_seconds,
        }
        if active:
            details["active"] = active
        if warm:
            details["warm"] = warm
        if reserved:
            details["reserved"] = reserved
        super().__init__(message, details)
        self.active = active
        self.warm = warm
        self.reserved = reserved
        self.replicas = replicas
        self.retry_after_seconds = retry_after_seconds
        self.reason = reason


class SandboxAuthorizationError(SandboxError):
    """Raised when the caller's role is denied sandbox execution.

    Phase 3 pluggable authorization: ``authorize("sandbox", "execute")`` is
    checked before sandbox acquisition. On deny this error propagates up
    through the tool's execution so the agent's tool-error handling converts
    it to a friendly ``ToolMessage`` ("sandbox not permitted for your role"),
    rather than crashing the run (RFC §9).
    """

    def __init__(
        self,
        message: str = "Sandbox execution is not permitted for your role",
        *,
        role: str | None = None,
    ) -> None:
        details = {"role": role} if role else None
        super().__init__(message, details)
        self.role = role

from pathlib import Path

from deerflow.sandbox.search import should_ignore_name


def list_dir(path: str, max_depth: int = 2) -> list[str]:
    """
    List files and directories up to max_depth levels deep.

    Args:
        path: The root directory path to list.
        max_depth: Maximum depth to traverse (default: 2).
                   1 = only direct children, 2 = children + grandchildren, etc.

    Returns:
        A list of absolute paths for files and directories,
        excluding items matching IGNORE_PATTERNS.
    """
    result: list[str] = []
    root_path = Path(path).resolve()

    if not root_path.is_dir():
        return result

    def _is_within_root(candidate: Path) -> bool:
        try:
            candidate.relative_to(root_path)
            return True
        except ValueError:
            return False

    def _traverse(current_path: Path, current_depth: int) -> None:
        """Recursively traverse directories up to max_depth."""
        if current_depth > max_depth:
            return

        try:
            for item in current_path.iterdir():
                if should_ignore_name(item.name):
                    continue

                if item.is_symlink():
                    try:
                        item_resolved = item.resolve()
                        if not _is_within_root(item_resolved):
                            continue
                    except OSError:
                        continue
                    post_fix = "/" if item_resolved.is_dir() else ""
                    result.append(str(item_resolved) + post_fix)
                    continue

                item_resolved = item.resolve()
                if not _is_within_root(item_resolved):
                    continue

                post_fix = "/" if item.is_dir() else ""
                result.append(str(item_resolved) + post_fix)

                # Recurse into subdirectories if not at max depth
                if item.is_dir() and current_depth < max_depth:
                    _traverse(item, current_depth + 1)
        except PermissionError:
            pass

    _traverse(root_path, 1)

    return sorted(result)

