"""Tests for AppConfig's name-indexed get_*_config lookups.

``get_model_config`` / ``get_tool_config`` / ``get_tool_group_config`` are
served from name -> config dicts built once after validation, instead of an
O(n) ``next(...)`` scan per call. These tests lock the indexed lookups to the
exact semantics of the linear scan they replaced (match, miss -> None,
first-match-wins on duplicate names) and confirm a config reload rebuilds them.
"""

from deerflow.config.app_config import AppConfig


def _build(model_names=(), tool_names=(), group_names=()):
    return AppConfig.model_validate(
        {
            "sandbox": {"use": "deerflow.sandbox.local:LocalSandboxProvider"},
            "models": [{"name": n, "use": "pkg:Cls", "model": n} for n in model_names],
            "tools": [{"name": n, "group": "default", "use": "pkg:fn"} for n in tool_names],
            "tool_groups": [{"name": n} for n in group_names],
        }
    )


def test_get_config_returns_matching_entry():
    cfg = _build(model_names=["m1", "m2"], tool_names=["t1", "t2"], group_names=["g1"])
    assert cfg.get_model_config("m2").name == "m2"
    assert cfg.get_tool_config("t1").name == "t1"
    assert cfg.get_tool_group_config("g1").name == "g1"


def test_get_config_returns_none_for_missing():
    cfg = _build(model_names=["m1"], tool_names=["t1"], group_names=["g1"])
    assert cfg.get_model_config("nope") is None
    assert cfg.get_tool_config("nope") is None
    assert cfg.get_tool_group_config("nope") is None


def test_get_config_first_match_wins_on_duplicate_names():
    # Two models share a name; the index must return the FIRST, matching the
    # previous next(...) scan.
    cfg = AppConfig.model_validate(
        {
            "sandbox": {"use": "deerflow.sandbox.local:LocalSandboxProvider"},
            "models": [
                {"name": "dup", "use": "pkg:A", "model": "first"},
                {"name": "dup", "use": "pkg:B", "model": "second"},
            ],
        }
    )
    assert cfg.get_model_config("dup").model == "first"


def test_index_matches_linear_scan_reference():
    cfg = _build(model_names=["a", "b", "c"], tool_names=["x", "y"], group_names=["g"])
    for n in ["a", "b", "c", "missing"]:
        assert cfg.get_model_config(n) == next((m for m in cfg.models if m.name == n), None)
    for n in ["x", "y", "missing"]:
        assert cfg.get_tool_config(n) == next((t for t in cfg.tools if t.name == n), None)
    for n in ["g", "missing"]:
        assert cfg.get_tool_group_config(n) == next((grp for grp in cfg.tool_groups if grp.name == n), None)


def test_empty_config_lookups_return_none():
    cfg = _build()
    assert cfg.get_model_config("anything") is None
    assert cfg.get_tool_config("anything") is None
    assert cfg.get_tool_group_config("anything") is None

"""The neutral Guardrail -> observer authorization handoff."""

from deerflow.authz.outcome import (
    _MAX_TRACKED_OUTCOMES,
    AUTHORIZATION_OUTCOME_CONTEXT_KEY,
    AuthorizationOutcome,
    pop_authorization_outcome,
    put_authorization_outcome,
)

OUTCOME = AuthorizationOutcome(decision="denied", policy_id="p", policy_version="1.0.0", reason_codes=("x",))


def test_round_trip_is_keyed_by_tool_call_id():
    context: dict = {}
    put_authorization_outcome(context, "call-1", OUTCOME)
    assert pop_authorization_outcome(context, "call-1") == OUTCOME


def test_pop_consumes_so_a_later_call_cannot_inherit_a_stale_decision():
    context: dict = {}
    put_authorization_outcome(context, "call-1", OUTCOME)
    pop_authorization_outcome(context, "call-1")
    assert pop_authorization_outcome(context, "call-1") is None


def test_context_key_is_double_underscore_prefixed_so_gateway_strips_forgeries():
    assert AUTHORIZATION_OUTCOME_CONTEXT_KEY.startswith("__")


def test_missing_context_or_tool_call_id_is_a_no_op_rather_than_an_error():
    put_authorization_outcome(None, "call-1", OUTCOME)
    put_authorization_outcome({}, None, OUTCOME)
    assert pop_authorization_outcome(None, "call-1") is None
    assert pop_authorization_outcome({}, None) is None


def test_the_store_evicts_the_oldest_entry_once_it_is_full():
    """No production caller pops entries yet, so an unbounded store would grow
    for the life of a run. Capping it keeps that growth to a fixed footprint."""
    context: dict = {}
    for i in range(_MAX_TRACKED_OUTCOMES + 1):
        put_authorization_outcome(context, f"call-{i}", OUTCOME)

    store = context[AUTHORIZATION_OUTCOME_CONTEXT_KEY]
    assert len(store) == _MAX_TRACKED_OUTCOMES
    assert "call-0" not in store
    assert f"call-{_MAX_TRACKED_OUTCOMES}" in store

"""Tests for build_principal_from_context — the single Principal builder.

This builder is the only sanctioned way to construct a Principal from runtime
context. Both Layer 1 (tool assembly) and Layer 2 (GuardrailAuthorizationAdapter)
must use it so identity semantics stay consistent.
"""

from __future__ import annotations

import pytest

from deerflow.authz.principal import build_principal_from_context


class TestPrincipalBuilderFields:
    """Verify all 7 Principal fields are explicitly constructed."""

    def test_empty_context(self):
        p = build_principal_from_context({}, default_role="user")
        assert p.user_id is None
        assert p.role == "user"
        assert p.oauth_provider is None
        assert p.oauth_id is None
        assert p.channel_user_id is None
        assert p.is_internal is False
        assert p.attributes == {}

    def test_full_field_mapping(self):
        context = {
            "user_id": "u1",
            "user_role": "admin",
            "oauth_provider": "github",
            "oauth_id": "gh-123",
            "channel_user_id": "ou_sender_1",
            "is_internal": True,
            "authz_attributes": {"department": "eng"},
        }
        p = build_principal_from_context(context, default_role="user")
        assert p.user_id == "u1"
        assert p.role == "admin"
        assert p.oauth_provider == "github"
        assert p.oauth_id == "gh-123"
        assert p.channel_user_id == "ou_sender_1"
        assert p.is_internal is True
        assert p.attributes == {"department": "eng"}

    def test_partial_context(self):
        context = {"user_id": "u1", "user_role": "user"}
        p = build_principal_from_context(context, default_role="admin")
        assert p.user_id == "u1"
        assert p.role == "user"
        assert p.oauth_provider is None
        assert p.oauth_id is None


class TestRoleResolution:
    """Role fallback rules."""

    def test_none_role_uses_default(self):
        p = build_principal_from_context({"user_role": None}, default_role="guest")
        assert p.role == "guest"

    def test_empty_string_role_uses_default(self):
        p = build_principal_from_context({"user_role": ""}, default_role="guest")
        assert p.role == "guest"

    def test_missing_role_uses_default(self):
        p = build_principal_from_context({}, default_role="guest")
        assert p.role == "guest"

    def test_unknown_role_preserved(self):
        """A non-empty but unknown role must NOT fall back to default_role."""
        p = build_principal_from_context({"user_role": "editor"}, default_role="user")
        assert p.role == "editor"


class TestIsInternalStrictBool:
    """is_internal must only be True when the value is strictly True."""

    @pytest.mark.parametrize(
        "value,expected",
        [
            (True, True),
            (False, False),
            (1, False),
            ("true", False),
            ("1", False),
            (None, False),
            ([], False),
            ({}, False),
        ],
    )
    def test_is_internal_strict_bool(self, value, expected):
        p = build_principal_from_context({"is_internal": value}, default_role="user")
        assert p.is_internal is expected


class TestAttributes:
    """Attributes copy and validation semantics."""

    def test_missing_attributes(self):
        p = build_principal_from_context({}, default_role="user")
        assert p.attributes == {}

    def test_none_attributes(self):
        p = build_principal_from_context({"authz_attributes": None}, default_role="user")
        assert p.attributes == {}

    def test_mapping_attributes_copied(self):
        attrs = {"team": "platform"}
        p = build_principal_from_context({"authz_attributes": attrs}, default_role="user")
        assert p.attributes == {"team": "platform"}
        # Mutating input after build must not affect Principal
        attrs["team"] = "changed"
        assert p.attributes["team"] == "platform"

