class TestProtocolConformance:
    def test_builtins_satisfy_protocol(self):
        for d in default_detectors():
            assert isinstance(d, SafetyTerminationDetector)

    def test_safety_termination_is_frozen(self):
        t = SafetyTermination(detector="x", reason_field="finish_reason", reason_value="content_filter")
        try:
            t.detector = "y"  # type: ignore[misc]
        except Exception:
            return
        raise AssertionError("SafetyTermination should be frozen")

"""Golden-vector tests for the shared sandbox scope token (RFC #4741).

The expected strings below are LITERALS computed from the five providers'
current inline expressions as of 2026-08-30. They pin the compatibility
contract byte-for-byte; never recompute them from the implementation.
"""

from deerflow.sandbox.identity import (
    SANDBOX_ID_VERSION,
    derive_sandbox_scope_token,
    is_sandbox_scope_token,
)


class TestGoldenVectors:
    def test_ascii(self):
        assert derive_sandbox_scope_token(user_id="alice", thread_id="thread-1") == "dc977b840cb8638e"

    def test_empty_user(self):
        # Tenki/OpenSandbox resolution path: user_id or ""
        assert derive_sandbox_scope_token(user_id="", thread_id="t") == "983743815e8fe2ac"

    def test_empty_thread(self):
        assert derive_sandbox_scope_token(user_id="u", thread_id="") == "27e14d2b41b03178"

    def test_non_ascii(self):
        assert derive_sandbox_scope_token(user_id="用户", thread_id="线程") == "cfa8a5bf41ddff8d"

    def test_literal_none_string(self):
        # BoxLite quirk: user_id=None renders as the literal "None" (RFC #4741
        # §2.2; pinned, NOT fixed — unifying is a separate behavior change).
        assert derive_sandbox_scope_token(user_id="None", thread_id="abc") == "c0b80df1b97d187e"

    def test_version_constant(self):
        assert SANDBOX_ID_VERSION == 1

    def test_keyword_only(self):
        import inspect

        sig = inspect.signature(derive_sandbox_scope_token)
        for param in sig.parameters.values():
            assert param.kind is inspect.Parameter.KEYWORD_ONLY


class TestShapeValidation:
    def test_accepts_token(self):
        token = derive_sandbox_scope_token(user_id="alice", thread_id="thread-1")
        assert is_sandbox_scope_token(token) is True

    def test_rejects_wrong_shape(self):
        assert is_sandbox_scope_token("") is False
        assert is_sandbox_scope_token("dc977b840cb8638") is False  # 15 chars
        assert is_sandbox_scope_token("dc977b840cb8638ee") is False  # 17 chars
        assert is_sandbox_scope_token("DC977B840CB8638E") is False  # uppercase
        assert is_sandbox_scope_token("local:alice:thread-1") is False

    def test_rejects_non_str(self):
        assert is_sandbox_scope_token(None) is False
        assert is_sandbox_scope_token(123) is False

from __future__ import annotations

import importlib.util
import subprocess
import sys
from pathlib import Path


def _load_module():
    repo_root = Path(__file__).resolve().parents[2]
    script_path = repo_root / "scripts" / "sandbox_memory_profile.py"
    spec = importlib.util.spec_from_file_location("sandbox_memory_profile", script_path)
    assert spec is not None
    module = importlib.util.module_from_spec(spec)
    assert spec.loader is not None
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    return module


def test_parse_memory_bytes_handles_kubernetes_units():
    mod = _load_module()

    assert mod.parse_memory_bytes("512Ki") == 512 * 1024
    assert mod.parse_memory_bytes("256Mi") == 256 * 1024 * 1024
    assert mod.parse_memory_bytes("1Gi") == 1024 * 1024 * 1024
    assert mod.parse_memory_bytes("0.1Gi") == 107374182
    assert mod.parse_memory_bytes("100M") == 100 * 1000 * 1000
    assert mod.parse_memory_bytes("bad") is None


def test_parse_top_pods_skips_header_and_preserves_raw_values():
    mod = _load_module()

    pods = mod.parse_top_pods(
        """NAME\tCPU(cores)\tMEMORY(bytes)
sandbox-abc 29m 792Mi
sandbox-def 1 501Mi
"""
    )

    assert [pod.name for pod in pods] == ["sandbox-abc", "sandbox-def"]
    assert pods[0].cpu_millicores == 29
    assert pods[0].memory_bytes == 792 * 1024 * 1024
    assert pods[1].cpu_millicores == 1000


def test_parse_processes_sorts_by_rss_and_limits_results():
    mod = _load_module()

    processes = mod.parse_processes(
        """PID\tPPID\tRSS\tCOMMAND
1 0 100 init
20 1 2048 python worker.py
21 1 bad ignored
30 1 512 node server.js
""",
        limit=2,
    )

    assert [(process.pid, process.rss_kib, process.command) for process in processes] == [
        (20, 2048, "python worker.py"),
        (30, 512, "node server.js"),
    ]


def test_parse_processes_rejects_invalid_limit():
    mod = _load_module()

    try:
        mod.parse_processes("1 0 100 init\n", limit=0)
    except ValueError as exc:
        assert "process limit" in str(exc)
    else:
        raise AssertionError("expected ValueError")


