    assert format_tool_result({"ok": True}) != ""

"""Tests for Session thread resolution (id-or-title) and lifecycle."""

from deerflow.tui.cli import LaunchPlan
from deerflow.tui.session import Session


class _Client:
    def __init__(self, threads):
        self._threads = threads

    def list_threads(self, limit=10):
        return {"thread_list": self._threads}


def _session(threads):
    return Session(client=_Client(threads))


THREADS = [
    {"thread_id": "thread-aaaa", "title": "Bug triage"},
    {"thread_id": "thread-bbbb", "title": "Write docs"},
]


def test_resolve_ref_matches_id():
    assert _session(THREADS).resolve_ref("thread-bbbb") == "thread-bbbb"


def test_resolve_ref_matches_title():
    assert _session(THREADS).resolve_ref("Bug triage") == "thread-aaaa"


def test_resolve_ref_unknown_falls_back_to_literal_id():
    assert _session(THREADS).resolve_ref("brand-new-id") == "brand-new-id"


def test_resolve_thread_resolves_title_from_plan():
    plan = LaunchPlan(mode="tui", thread_id="Write docs")
    assert _session(THREADS).resolve_thread(plan) == "thread-bbbb"


def test_resolve_thread_continue_returns_most_recent():
    plan = LaunchPlan(mode="tui", continue_recent=True)
    assert _session(THREADS).resolve_thread(plan) == "thread-aaaa"


def test_close_is_a_noop_without_a_loop():
    # Headless sessions have no persistence loop; close() must be safe.
    _session(THREADS).close()


def test_close_stops_the_background_loop():
    from deerflow.tui.persistence import ThreadMetaWriter, _LoopThread

    loop = _LoopThread()
    session = Session(client=_Client(THREADS), writer=ThreadMetaWriter(loop, None), _loop=loop)
    session.close()
    assert session._loop is None
    session.close()  # idempotent

"""Tests for runtime.user_context — contextvar three-state semantics.

These tests opt out of the autouse contextvar fixture (added in
commit 6) because they explicitly test the cases where the contextvar
is set or unset.
"""

from types import SimpleNamespace

import pytest
from langchain_core.runnables import RunnableLambda
from langgraph.runtime import Runtime, ServerInfo

from deerflow.config.paths import Paths, make_safe_user_id
from deerflow.runtime.user_context import (
    DEFAULT_USER_ID,
    CurrentUser,
    get_current_user,
    get_effective_user_id,
    require_current_user,
    reset_current_user,
    resolve_config_user_id,
    resolve_runtime_user_id,
    set_current_user,
)


@pytest.mark.no_auto_user
def test_default_is_none():
    """Before any set, contextvar returns None."""
    assert get_current_user() is None


@pytest.mark.no_auto_user
def test_set_and_reset_roundtrip():
    """set_current_user returns a token that reset restores."""
    user = SimpleNamespace(id="user-1")
    token = set_current_user(user)
    try:
        assert get_current_user() is user
    finally:
        reset_current_user(token)
    assert get_current_user() is None


@pytest.mark.no_auto_user
def test_require_current_user_raises_when_unset():
    """require_current_user raises RuntimeError if contextvar is unset."""
    assert get_current_user() is None
    with pytest.raises(RuntimeError, match="without user context"):
        require_current_user()


@pytest.mark.no_auto_user
def test_require_current_user_returns_user_when_set():
    """require_current_user returns the user when contextvar is set."""
    user = SimpleNamespace(id="user-2")
    token = set_current_user(user)
    try:
        assert require_current_user() is user
    finally:
        reset_current_user(token)


@pytest.mark.no_auto_user
def test_protocol_accepts_duck_typed():
    """CurrentUser is a runtime_checkable Protocol matching any .id-bearing object."""
    user = SimpleNamespace(id="user-3")
    assert isinstance(user, CurrentUser)


@pytest.mark.no_auto_user
def test_protocol_rejects_no_id():
    """Objects without .id do not satisfy CurrentUser Protocol."""
    not_a_user = SimpleNamespace(email="no-id@example.com")
    assert not isinstance(not_a_user, CurrentUser)


